      source: "spox",
      source_type: "rss",
      url: "https://feeds.footballco.com/spox/feed/in9xv2rmbt7qjzpk"
    }
  },
  {
    json: {
      source: "fussballtransfers",
      source_type: "rss",
      url: "https://www.fussballtransfers.com/rss-feed"
    }
  }
];

const items = $input.all();

const out = [];
const seen = new Set();

const sourceConfig = {
  sport1: {
    baseUrl: 'https://www.sport1.de',
    articleIncludes: ['/news/'],
    articleExcludes: ['/news', '/news/'],
  },
  sky: {
    baseUrl: 'https://sport.sky.de',
    articleIncludes: ['/fussball/artikel/'],
    articleExcludes: [],
  },
  transferfeed: {
    baseUrl: 'https://www.transferfeed.com',
    articleIncludes: ['/transfers/'],
    articleExcludes: ['/transfers', '/transfers/'],
  }
};

const blockedPatterns = [
  '/apps',
  '/app',
  '/nutzungsbedingungen',
  '/agb',
  '/impressum',
  '/datenschutz',
  '/unternehmen',
  '/tv',
  '/live',
  '/video',
  '/ergebnisse',
  '/spielplan',
  '/kader',
  '/tabelle',
  '/statistiken',
  '/highlights',
  '/live-ticker',
  '#'
];

for (const item of items) {
  const links = item.json.link || [];
  const sourceName = item.json.source_name || '';
  const sourceType = item.json.source_type || 'web';
  const sourceCategory = item.json.source_category || 'football';

  const config = sourceConfig[sourceName];
  if (!config) continue;

  for (const rawLink of links) {
    if (!rawLink || typeof rawLink !== 'string') continue;

    const link = rawLink.trim();
    if (!link) continue;

    const absoluteUrl = link.startsWith('http')
      ? link
      : `${config.baseUrl}${link.startsWith('/') ? '' : '/'}${link}`;

    const urlLower = absoluteUrl.toLowerCase();

    if (!urlLower.startsWith(config.baseUrl.toLowerCase())) continue;

    const matchesArticlePattern = config.articleIncludes.some(pattern =>
      urlLower.includes(pattern)
    );
    if (!matchesArticlePattern) continue;

    const isExplicitlyExcluded = config.articleExcludes.some(pattern =>
      urlLower === `${config.baseUrl.toLowerCase()}${pattern}` || urlLower.endsWith(pattern)
    );
    if (isExplicitlyExcluded) continue;

    const isBlocked = blockedPatterns.some(pattern =>
      urlLower.includes(pattern)
    );
    if (isBlocked) continue;

    if (seen.has(absoluteUrl)) continue;
    seen.add(absoluteUrl);

    out.push({
      json: {
        url: absoluteUrl,
        source_name: sourceName,
        source_type: sourceType,
        source_category: sourceCategory
      }
    });
  }
}

return out;

const url = ($json.url || '').toLowerCase();

if (!url) {
  return null;
}

// Harte Ausschlüsse: klare Nicht-Fußball-Bereiche
if (
  url.includes('/motorsport') ||
  url.includes('/formel1') ||
  url.includes('/reiten') ||
  url.includes('/wrestling') ||
  url.includes('/wintersport') ||
  url.includes('/ski') ||
  url.includes('/leichtathletik') ||
  url.includes('/darts') ||
  url.includes('/eishockey') ||
  url.includes('/tennis') ||
  url.includes('/us-sport') ||
  url.includes('/basketball') ||
  url.includes('/handball')
) {
  return null;
}

return $json;

const output = [];

/**
 * Blockierte Muster für RSS-Artikel
 * Kannst du später leicht erweitern
 */
const blockedTitlePatterns = [
  'live!',
  'liveticker',
  'ticker',
  'video:',
  'bilder:',
  'fotostrecke'
];

const blockedUrlPatterns = [
  '/live',
  '/liveticker',
  '/video',
  '/bilder',
  '/bildstrecke',
  '/fotostrecke'
];

for (const item of items) {
  const channel = item.json?.rss?.channel;

  if (!channel || !channel.item) continue;

  const articles = Array.isArray(channel.item)
    ? channel.item
    : [channel.item];

  for (const article of articles) {
    const title = (article.title || '').trim();
    const description = (article.description || '').trim();
    const url = (article.link || '').trim();
    const published_at = article.pubDate || '';

    // Grundvalidierung
    if (!title || !url) continue;

    const titleLower = title.toLowerCase();
    const urlLower = url.toLowerCase();

    // Noise / unerwünschte Formate raus
    const blockedByTitle = blockedTitlePatterns.some(pattern =>
      titleLower.includes(pattern)
    );

    const blockedByUrl = blockedUrlPatterns.some(pattern =>
      urlLower.includes(pattern)
    );

    if (blockedByTitle || blockedByUrl) continue;

    const raw_text = description;
    const search_text = `${title} ${description}`.toLowerCase();

    output.push({
      json: {
        source: channel.link || '',
        source_type: 'rss',
        source_category: 'football',
        url,
        published_at,
        title,
        description,
        raw_text,
        search_text
      }
    });
  }
}

return output;

const output = [];

for (const item of items) {
  const data = item.json;

  output.push({
    json: {
      title: (data.title || '').trim(),
      raw_text: (data.raw_text || '').trim(),
      description: (data.description || '').trim(),
      url: data.url || '',
      published_at: data.published_at || '',
      source: data.source || data.source_name || '',
      source_type: data.source_type || 'web',
      source_category: data.source_category || ''
    }
  });
}

return output;

const output = [];

for (const item of items) {
  const data = item.json;

  const title = (
    data.og_title ||
    data["og:title"] ||
    data.title ||
    ""
  ).trim();

  const description = (
    data.og_description ||
    data["og:description"] ||
    ""
  ).trim();

  const raw_text = `${title} ${description}`.trim();
  const search_text = raw_text.toLowerCase();

  output.push({
    json: {
      source: data.source || "sport1",
      source_type: "web",
      source_category: "football",
      url: data.url || "",
      published_at: data.published_at || "",
      title,
      description,
      raw_text,
      search_text
    }
  });
}

return output;

function decodeXml(value) {
  return String(value || "")
    .replace(/<!\[CDATA\[/g, "")
    .replace(/\]\]>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .trim();
}

function stripHtml(value) {
  return String(value || "")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalize(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/[ä]/g, "ae")
    .replace(/[ö]/g, "oe")
    .replace(/[ü]/g, "ue")
    .replace(/[ß]/g, "ss")
    .replace(/[éèêë]/g, "e")
    .replace(/[áàâã]/g, "a")
    .replace(/[íìîï]/g, "i")
    .replace(/[óòôõ]/g, "o")
    .replace(/[úùû]/g, "u")
    .replace(/[ç]/g, "c")
    .replace(/[ñ]/g, "n")
    .replace(/<img[^>]*>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/https?:\/\/\S+/gi, " ")
    .replace(/&[a-z0-9#]+;/gi, " ")
    .replace(/[^\w\s\-\/]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeKey(value) {
  return normalize(value)
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function hasAny(text, patterns) {
  const t = normalize(text);
  return patterns.some(pattern => pattern.test(t));
}

function uniqueList(values) {
  return Array.from(new Set(values.filter(Boolean)));
}

function getTag(itemXml, tagName) {
  const regex = new RegExp(`<${tagName}[^>]*>([\\s\\S]*?)<\\/${tagName}>`, "i");
  const match = String(itemXml || "").match(regex);
  return match ? decodeXml(match[1]) : "";
}

function parseDate(value) {
  const raw = String(value || "").trim();

  if (!raw) return new Date();

  const cleaned = raw
    .replace(/\bCEST\b/gi, "+0200")
    .replace(/\bCET\b/gi, "+0100");

  const date = new Date(cleaned);
  return Number.isNaN(date.getTime()) ? new Date() : date;
}

function normalizeDate(rawDate) {
  const raw = String(rawDate || "").trim();

  if (!raw) return "";

  const cleaned = raw
    .replace(/\bCEST\b/gi, "+0200")
    .replace(/\bCET\b/gi, "+0100");

  const date = new Date(cleaned);
  return Number.isNaN(date.getTime()) ? raw : date.toISOString();
}

function getDateBucketFromRaw(rawDate) {
  return parseDate(rawDate).toISOString().slice(0, 10);
}

function stripDateFromFingerprint(fp) {
  return String(fp || "").replace(/^\d{4}-\d{2}-\d{2}_/, "");
}

const entityPatterns = [
