const schalkePlayerEntities = new Set(entityPatterns.filter(e => e.type === "schalke_player").map(e => e.key));
const formerS04PlayerEntities = new Set(entityPatterns.filter(e => e.type === "former_schalke_player").map(e => e.key));
const schalkeStaffEntities = new Set(entityPatterns.filter(e => e.type === "staff" || e.type === "legend").map(e => e.key));
const transferCandidateEntities = new Set(entityPatterns.filter(e => e.type === "transfer_candidate").map(e => e.key));
const knownPlayerEntities = new Set(entityPatterns.filter(e => ["schalke_player", "former_schalke_player", "transfer_candidate"].includes(e.type)).map(e => e.key));

function entityType(entity) {
  const item = entityPatterns.find(e => e.key === entity);
  if (item) return item.type;
  if (String(entity || "").endsWith("_alternative")) return "transfer_alternative_cluster";
  return "";
}

function isS04PlayerEntity(entity) {
  return schalkePlayerEntities.has(entity);
}

function isFormerS04PlayerEntity(entity) {
  return formerS04PlayerEntities.has(entity);
}

function isS04StaffEntity(entity) {
  return schalkeStaffEntities.has(entity);
}

function isTransferCandidateEntity(entity) {
  return transferCandidateEntities.has(entity);
}

function isPlayerEntity(entity) {
  if (!entity) return false;
  if (knownPlayerEntities.has(entity)) return true;
  if (String(entity).endsWith("_alternative")) return true;
  return /^[a-z0-9_]{4,}$/.test(normalizeKey(entity));
}

function hasS04ClubText(text) {
  const t = normalize(text);

  return hasAny(t, [
    /\bfc schalke 04\b/,
    /\bschalke 04\b/,
    /\bschalke\b/,
    /\bs04\b/,
    /\bknappen\b/,
    /\bkoenigsblau/,
    /\bveltins-arena\b/,
    /\barena aufschalke\b/
  ]);
}

function detectOpponent(text) {
  const t = normalize(text);

  const opponents = [
    { key: "psv", patterns: [/\bpsv\b/, /\beindhoven\b/] },
    { key: "hertha", patterns: [/\bhertha\b/, /\bhertha bsc\b/] },
    { key: "tottenham", patterns: [/\btottenham\b/, /\bspurs\b/] },
    { key: "sporting", patterns: [/\bsporting\b/, /\bsporting lissabon\b/] },
    { key: "arsenal", patterns: [/\barsenal\b/] },
    { key: "chelsea", patterns: [/\bchelsea\b/] },
    { key: "liverpool", patterns: [/\bliverpool\b/] },
    { key: "man_city", patterns: [/\bmanchester city\b/, /\bman city\b/] },
    { key: "man_united", patterns: [/\bmanchester united\b/, /\bman united\b/] },
    { key: "newcastle", patterns: [/\bnewcastle\b/] },
    { key: "barcelona", patterns: [/\bbarcelona\b/, /\bbarca\b/] },
    { key: "real_madrid", patterns: [/\breal madrid\b/, /\bgegen real\b/] },
    { key: "psg", patterns: [/\bpsg\b/, /\bparis saint germain\b/] },
    { key: "inter", patterns: [/\binter mailand\b/, /\binter\b/] },
    { key: "milan", patterns: [/\bac mailand\b/, /\bac milan\b/, /\bmilan\b/] },
    { key: "juventus", patterns: [/\bjuventus\b/, /\bjuve\b/] },
    { key: "bayern", patterns: [/\bbayern\b/, /\bfc bayern\b/, /\bbayern muenchen\b/, /\bfcb\b/] },
    { key: "dortmund", patterns: [/\bdortmund\b/, /\bbvb\b/, /\bborussia dortmund\b/] },
    { key: "leverkusen", patterns: [/\bleverkusen\b/, /\bbayer 04\b/] },
    { key: "leipzig", patterns: [/\bleipzig\b/, /\brb leipzig\b/] },
    { key: "stuttgart", patterns: [/\bstuttgart\b/, /\bvfb\b/] },
    { key: "frankfurt", patterns: [/\bfrankfurt\b/, /\beintracht\b/] },

    { key: "senegal", patterns: [/\bsenegal\b/] },
    { key: "kolumbien", patterns: [/\bkolumbien\b/, /\bcolombia\b/] },
    { key: "costa_rica", patterns: [/\bcosta rica\b/] },
    { key: "kanada", patterns: [/\bkanada\b/, /\bcanada\b/] },
    { key: "bosnien", patterns: [/\bbosnien\b/, /\bbosnia\b/] },
    { key: "deutschland", patterns: [/\bdeutschland\b/, /\bdfb\b/] },
    { key: "frankreich", patterns: [/\bfrankreich\b/, /\bfrance\b/] },
    { key: "oesterreich", patterns: [/\boesterreich\b/, /\baustria\b/] },
    { key: "marokko", patterns: [/\bmarokko\b/, /\bmorocco\b/] },
    { key: "usa", patterns: [/\busa\b/, /\bunited states\b/] }
  ];

  for (const opponent of opponents) {
    if (opponent.patterns.some(pattern => pattern.test(t))) {
      return opponent.key;
    }
  }

  return "";
}

function hasTransferOrPlayerTopic(text) {
  const t = normalize(text);

  return hasAny(t, [
