  if (hasAny(t, [
    /\bangebot\b.*\beingereicht\b/,
    /\bofferte\b.*\beingereicht\b/,
    /\bgebot\b.*\beingereicht\b/,
    /\blegt\b.*\bangebot\b.*\bvor\b/,
    /\berstes angebot\b.*\bvor\b/
  ])) return "offer_submitted";

  if (hasAny(t, [
