  ])) return "price";

  if (transferNewsAngle === "breakthrough") return "breakthrough";
  if (transferNewsAngle === "talks_update") return "talks";
  if (transferNewsAngle === "push") return "push";
  if (transferNewsAngle === "poker_update") return "poker_update";
  if (transferNewsAngle === "decision_update") return "decision_timeline";
  if (transferNewsAngle === "details") return "details_update";

  if (hasAny(t, [
    /\bverhandlungen\b/,
