  ])) return "decision_timeline";

  if (hasAny(t, [
    /\bplan\s*b\b/,
    /\balternative\b/,
    /\boption\b/,
    /\bnach\b.*\b(scheitern|geplatzt|absage|aus)\b/,
    /\bneue[nrsm]?\s+(fluegelspieler|offensivspieler|angreifer|stuermer|verteidiger|kandidat|option|loesung)\b/
  ])) return "alternative_search";

  return "interest";
}

function detectTransferPhase(text) {
  const development = detectTransferDevelopmentDetail(text);

  if (development === "completed") return "completed";
  if (development === "schalke_lost") return "schalke_lost";
  if (development === "rejection") return "rejection";
  if (development === "club_blocks") return "club_blocks";
  if (development === "player_greenlight") return "player_greenlight";
  if (["offer_submitted", "offer_planned", "offer"].includes(development)) return "offer";
  if (["club_agreement", "talks"].includes(development)) return "talks";
  if (["breakthrough", "push", "poker_update", "details_update"].includes(development)) return "talks";
  if (["cost_package", "price"].includes(development)) return "price";
  if (development === "decision_timeline") return "decision";
  if (development === "alternative_search") return "club_interest";

  return "general";
}

function normalizeTransferPhaseForDuplicates(phase, text) {
  const t = normalize(text);
  const p = String(phase || "general");

  if ([
    "completed",
    "schalke_lost",
    "rejection",
    "club_blocks",
    "player_greenlight",
    "offer",
    "talks",
    "price",
    "decision"
  ].includes(p)) {
    return p;
  }

  if (
    ["club_interest", "general"].includes(p) ||
    hasAny(t, [
      /\binteresse\b/,
      /\binteressiert\b/,
      /\bbeobachtet\b/,
      /\bscoutet\b/,
      /\bprueft\b/,
      /\bkandidat\b/,
      /\bwunschziel\b/,
      /\btransferziel\b/,
      /\boption\b/,
      /\balternative\b/,
      /\bpoker\b/,
      /\bmitbieten\b/,
      /\bablosefrei\b/
    ])
  ) {
    return "interest";
  }

  return p || "general";
}

function detectTransferSubangle(text, entity, opponent, speaker) {
  const t = normalize(text);
  const phase = detectTransferPhase(t);
  const normalizedPhase = normalizeTransferPhaseForDuplicates(phase, t);
  const development = detectTransferDevelopmentDetail(t);

  const playerExplanation = hasAny(t, [
    /\bspricht ueber schalke\b/,
    /\bspricht ueber .* wechsel\b/,
    /\bspricht ueber .* transfer\b/,
    /\bwarum\b.*\bwechsel\b.*\b(scheiterte|scheitert|platzte|geplatzt)\b/,
    /\bwechsel nach (gelsenkirchen|schalke)\b.*\b(scheiterte|scheitert|platzte|geplatzt)\b/,
    /\berklaert\b.*\b(scheitern|absage|wechsel|transfer)\b/,
    /\bbegruendet\b.*\b(absage|wechsel|transfer)\b/
  ]);

  if (playerExplanation) {
    return {
      subangle: "player_explanation_failed_schalke_move",
      stage: "player_explanation",
      stage_rank: 86,
      detail: "player_explanation"
    };
  }

  const thirdPartyReaction = hasAny(t, [
    /\bstichelt\b/,
    /\bspottet\b/,
    /\bseitenhieb\b/,
    /\breagiert\b/,
    /\bkontert\b/,
    /\bkommentiert\b/,
    /\bfindet klare worte\b/,
    /\bmeint\b/,
    /\bsagt\b.*\b(absage|wechsel|transfer|entscheidung)\b/,
    /\bspricht\b.*\b(absage|wechsel|transfer|entscheidung)\b/
  ]) && Boolean(speaker);

  if (thirdPartyReaction) {
    return {
      subangle: speaker ? `reaction_${speaker}` : "reaction",
      stage: "reaction",
      stage_rank: 85,
      detail: "third_party_reaction"
    };
  }

  if (development === "alternative_search" || String(entity || "").endsWith("_alternative")) {
    return {
      subangle: entity ? `${entity}_alternative_search` : "alternative_search",
      stage: "interest",
      stage_rank: 20,
      detail: "alternative_after_failed_primary_target"
    };
  }

  const mapping = {
    completed: { subangle: opponent ? `completed_${opponent}` : "completed", stage: "completed", stage_rank: 80 },
    schalke_lost: { subangle: opponent ? `schalke_lost_${opponent}` : "schalke_lost", stage: "schalke_lost", stage_rank: 65 },
    rejection: { subangle: "rejection", stage: "rejection", stage_rank: 60 },
    club_blocks: { subangle: opponent ? `club_blocks_${opponent}` : "club_blocks", stage: "club_blocks", stage_rank: 58 },
    breakthrough: { subangle: opponent ? `breakthrough_${opponent}` : "breakthrough", stage: "breakthrough", stage_rank: 55 },
    club_agreement: { subangle: opponent ? `club_agreement_${opponent}` : "club_agreement", stage: "talks", stage_rank: 48 },
    push: { subangle: opponent ? `push_${opponent}` : "push", stage: "talks", stage_rank: 46 },
    poker_update: { subangle: opponent ? `poker_update_${opponent}` : "poker_update", stage: "talks", stage_rank: 44 },
    details_update: { subangle: opponent ? `details_${opponent}` : "details", stage: "details", stage_rank: 42 },
    player_greenlight: { subangle: "player_greenlight", stage: "player_greenlight", stage_rank: 45 },
    offer_submitted: { subangle: "offer_submitted", stage: "offer", stage_rank: 52 },
    offer_planned: { subangle: "offer_planned", stage: "offer", stage_rank: 50 },
    offer: { subangle: "offer", stage: "offer", stage_rank: 50 },
    cost_package: { subangle: "cost_package", stage: "price", stage_rank: 38 },
    price: { subangle: "price", stage: "price", stage_rank: 35 },
    decision_timeline: { subangle: "decision_timeline", stage: "decision", stage_rank: 32 },
    talks: { subangle: "talks", stage: "talks", stage_rank: 40 }
  };

  if (mapping[development]) {
    return {
      ...mapping[development],
      detail: development
    };
  }

  if (normalizedPhase === "talks") {
    return { subangle: "talks", stage: "talks", stage_rank: 40, detail: phase };
  }

  return { subangle: "interest", stage: "interest", stage_rank: 20, detail: phase };
}

function detectFuturePhase(text) {
  const t = normalize(text);

  if (hasAny(t, [/\bverkauf\b/, /\bverkaufen\b/, /\bverkaufsliste\b/, /\bstreichliste\b/, /\bpreisschild\b/, /\babgangskandidat\b/, /\bverkaufskandidat\b/])) return "sale";
  if (hasAny(t, [/\babgang\b/, /\babschied\b/, /\bverlaesst\b/, /\bwechsel\b/, /\bvor abschied\b/, /\bvor abgang\b/, /\bneuer klub\b/])) return "exit";
  if (hasAny(t, [/\bnicht\s+zu\s+verkaufen\b/, /\bunverkaeuflich\b/, /\bkeine\s+freigabe\b/, /\bbleibt\b/, /\bbleiben\b/, /\bnicht verlassen\b/, /\bsoll bleiben\b/, /\bstellt sich quer\b/])) return "retention";
  if (hasAny(t, [/\bvertrag\b/, /\bverlaengert\b/, /\bverlaengerung\b/, /\bvertragsverlaengerung\b/])) return "contract";
  if (hasAny(t, [/\bleihe\b/, /\bausleihe\b/, /\bkaufoption\b/, /\brueckkehr\b/, /\brueckkehrer\b/])) return "loan";
  if (hasAny(t, [/\brolle\b/, /\bsituation\b/, /\bmissverstaendnis\b/, /\benttaeuschung\b/, /\bproblem\b/, /\bkaum einsatzzeit\b/, /\breservist\b/])) return "role";
  if (hasAny(t, [/\bgehalt\b/, /\bmillionenverlust\b/, /\bteuer\b/, /\bkosten\b/, /\bmarktwert\b/])) return "finance";

  return "general";
}

function detectInjuryPhase(text) {
  const t = normalize(text);

  const hasInjuryContext = hasAny(t, [
    /\bverletz/,
