    "fuer", "ueber", "aus", "dem", "den", "des", "dass", "sich", "hat", "haben",
    "mehr", "wie", "so", "es", "er", "sie", "sein", "ihre", "ihren", "ihm",
    "beim", "bevor", "jetzt", "wohl", "offenbar", "laut", "bericht", "berichte",
    "schalke", "fc", "gelsenkirchen", "rekordmeister", "bild", "sportbild", "kicker"
  ]);

  return normalize(text)
    .split(/\s+/)
    .map(word => normalizeKey(word))
    .filter(word => word && word.length >= 3 && !noise.has(word))
    .slice(0, 10);
}

function buildFallbackFingerprint(topic, entity, opponent, text) {
  const words = cleanWords(text).slice(0, 4).join("_");
  return normalizeKey([topic, entity, opponent, words].filter(Boolean).join("_")) || "general_unknown";
}

function buildFingerprint(input) {
  const json = input.json || input;

  const title = stripHtml(decodeXml(json.title || ""));
  const description = stripHtml(decodeXml(json.description || ""));
  const rawText = stripHtml(decodeXml(json.raw_text || json.content || json.contentSnippet || ""));
  const url = String(json.url || json.link || "").trim();

  const searchText = [
    title,
    description,
    rawText,
    url
  ].filter(Boolean).join(" ");

  const cleanedSearchText = normalize(searchText);

  const opponent = detectOpponent(cleanedSearchText);
  const entity = detectEntity(cleanedSearchText, searchText);
  const speaker = detectSpeakerEntity(cleanedSearchText, entity);
  const topic = detectTopic(cleanedSearchText, opponent, entity, speaker);

  const transferProfile = detectTransferProfile(cleanedSearchText);
  const transferPhase = detectTransferPhase(cleanedSearchText);
  const transferPhaseNormalized = normalizeTransferPhaseForDuplicates(transferPhase, cleanedSearchText);
  const transferSub = detectTransferSubangle(cleanedSearchText, entity, opponent, speaker);

  const futurePhase = detectFuturePhase(cleanedSearchText);
  const injuryPhase = detectInjuryPhase(cleanedSearchText);
  const statementAngle = detectStatementAngle(cleanedSearchText);
  const financePhase = detectFinancePhase(cleanedSearchText);

  const legacyType = detectLegacyType(cleanedSearchText, entity);
  const dfbType = detectDfbCurrentS04PlayerType(cleanedSearchText, entity);
  const schalkeAffinityType = detectS04AffinityType(cleanedSearchText);
  const multisportType = detectMultisportType(cleanedSearchText, entity);
  const awardType = detectAwardType(cleanedSearchText);
  const ratingType = detectRatingType(cleanedSearchText);
  const teamUnit = detectTeamUnit(cleanedSearchText);
  const entityGroup = detectEntityGroup(cleanedSearchText, entity);
  const clubStrategyType = detectClubStrategyType(cleanedSearchText, entity);
  const dfbMatchOpponent = detectNationalTeamMatchOpponent(cleanedSearchText);
  const dfbCluster = detectDfbStoryCluster(cleanedSearchText, entity);
  const socialBuzzType = detectClubSocialBuzzType(cleanedSearchText);
  const clubEventType = detectClubEventType(cleanedSearchText);
  const clubEventProduct = detectClubEventProduct(cleanedSearchText);
  const fanServiceType = detectFanServiceType(cleanedSearchText);
  const staffSituationType = detectStaffSituationType(cleanedSearchText, entity);
  const tournamentBenefitType = detectTournamentBenefitType(cleanedSearchText);

  const dateBucket = getDateBucketFromRaw(json.published_at || json.publishedAt || json.pubDate || json.isoDate || json.date || json.created_at || "");

  const entitySafe = entity || entityGroup || "unknown";
  const opponentSafe = opponent || "";
  const topicSafe = topic || "general";

  let fingerprintKey = "";
  let storyThreadKey = "";
  let storyTopic = topicSafe;
  let storyEntity = entitySafe;
  let storyStage = "general";
  let storyStageRank = 10;
  let storyStageDetail = "general";
  let storyUpdateStageKey = "";

  if (topicSafe === "transfer" || topicSafe === "transfer_geruecht") {
    storyTopic = "transfer";
    storyEntity = entitySafe;
    storyStage = transferSub.stage || transferPhaseNormalized || "interest";
    storyStageRank = transferSub.stage_rank || 20;
    storyStageDetail = transferSub.detail || transferSub.subangle || "general";

    fingerprintKey = normalizeKey([
      "transfer",
      entitySafe,
      transferSub.subangle || transferPhaseNormalized || "interest"
    ].filter(Boolean).join("_"));

    storyThreadKey = normalizeKey([
      "transfer",
      entitySafe
    ].filter(Boolean).join("_"));

    storyUpdateStageKey = normalizeKey([
      "transfer",
      entitySafe,
      storyStage,
      storyStageDetail
    ].filter(Boolean).join("_"));
  } else if (topicSafe === "verletzung") {
    storyTopic = "verletzung";
    storyEntity = entitySafe;
    storyStage = injuryPhase;
    storyStageRank =
      injuryPhase === "diagnose" ? 70 :
      injuryPhase === "ausfall" ? 60 :
      injuryPhase === "comeback" ? 50 :
      injuryPhase === "fraglich" ? 30 :
      injuryPhase === "personal_reaction" ? 40 :
      injuryPhase === "external_reaction" ? 35 :
      20;

    storyStageDetail = injuryPhase;

    fingerprintKey = normalizeKey(["verletzung", entitySafe, injuryPhase].join("_"));
    storyThreadKey = normalizeKey(["verletzung", entitySafe].join("_"));
    storyUpdateStageKey = fingerprintKey;
  } else if (topicSafe === "zukunft") {
    storyTopic = "zukunft";
    storyEntity = entitySafe;
    storyStage = futurePhase;
    storyStageRank =
      futurePhase === "contract" ? 60 :
      futurePhase === "retention" ? 55 :
      futurePhase === "exit" ? 50 :
      futurePhase === "sale" ? 45 :
      futurePhase === "loan" ? 40 :
      futurePhase === "role" ? 30 :
      20;

    storyStageDetail = futurePhase;

    fingerprintKey = normalizeKey(["zukunft", entitySafe, futurePhase].join("_"));
    storyThreadKey = normalizeKey(["zukunft", entitySafe].join("_"));
    storyUpdateStageKey = fingerprintKey;
  } else if (topicSafe === "aussage") {
    storyTopic = "aussage";
    storyEntity = entitySafe;
    storyStage = statementAngle;
    storyStageRank =
      statementAngle === "kritik" ? 50 :
      statementAngle === "debatte" ? 45 :
      statementAngle === "lob" ? 35 :
      statementAngle === "prognose" ? 30 :
      20;

    storyStageDetail = speaker ? `${statementAngle}_${speaker}` : statementAngle;

    fingerprintKey = normalizeKey(["aussage", entitySafe, speaker, statementAngle].filter(Boolean).join("_"));
    storyThreadKey = normalizeKey(["aussage", entitySafe].join("_"));
    storyUpdateStageKey = fingerprintKey;
  } else if (topicSafe === "finanzen") {
    storyTopic = "finanzen";
