    fingerprintKey = normalizeKey(["player_rating", storyEntity, storyStageDetail].join("_"));
    storyThreadKey = normalizeKey(["player_rating", storyEntity].join("_"));
    storyUpdateStageKey = fingerprintKey;
  } else if (topicSafe === "club_strategy") {
