    storyThreadKey = "club_social_buzz_fc_schalke";
    storyUpdateStageKey = fingerprintKey;
  } else if (topicSafe === "club_event") {
    storyTopic = "club_event";
    storyEntity = "fc_schalke";
    storyStage = clubEventType || "general";
    storyStageRank = 15;
