(() => {
  function formatDate(raw) {
    if (!raw) return "kein Datum vorhanden";

    const value = String(raw).trim();

    const cleaned = value
      .replace(/\bCEST\b/gi, "+0200")
      .replace(/\bCET\b/gi, "+0100");

    let dt = DateTime.fromISO(cleaned, { zone: "Europe/Berlin" });

    if (!dt.isValid) {
      dt = DateTime.fromRFC2822(cleaned, { zone: "Europe/Berlin" });
    }

    if (!dt.isValid) {
      const jsDate = new Date(cleaned);
      if (!Number.isNaN(jsDate.getTime())) {
        dt = DateTime.fromJSDate(jsDate).setZone("Europe/Berlin");
      }
    }

    if (!dt.isValid && $json.content_fingerprint) {
      const match = String($json.content_fingerprint).match(/^(\d{4})-(\d{2})-(\d{2})/);
      if (match) {
        return `${match[3]}.${match[2]}.${match[1]}`;
      }
    }

    return dt.isValid ? dt.setZone("Europe/Berlin").toFormat("dd.MM.yyyy, HH:mm 'Uhr'") : "kein Datum vorhanden";
  }

  const publishedDate = formatDate(
    $json.published_at ||
    $json.publishedAt ||
    $json.pubDate ||
    $json.isoDate ||
    $json.date
  );

  return (
    "📅 Datum:\n" +
    publishedDate +

    "\n\n💬 Social:\n" +
    ($json.generated_social || $json.social_caption || "") +

    "\n\n---\n🔗 Link:\n" +
    ($json.source_url || $json.url || "") +

    "\n\n⚡ Priorität:\n" +
    (($json.priority ?? $json.priority_label) ?? "noch nicht bewertet") +

    "\n\n---\n🤖 KI-/System-Output\n\nGenerated Title:\n" +
    ($json.generated_trello_title || $json.generated_title || $json.trello_title || $json.title || "") +

    "\n\nGenerated Social:\n" +
    ($json.generated_social || $json.social_caption || "") +

    "\n\nOriginal Title:\n" +
    ($json.source_title || $json.title || "")
  );
})()
}}

