function stringifyError(value) {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;

  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  if (typeof value === "object") {
    const parts = [];

    if (value.message) parts.push(String(value.message));
    if (value.status) parts.push(`status:${value.status}`);
    if (value.statusCode) parts.push(`statusCode:${value.statusCode}`);
    if (value.code) parts.push(`code:${value.code}`);
    if (value.response?.status) parts.push(`response_status:${value.response.status}`);
    if (value.response?.statusText) parts.push(`response_status_text:${value.response.statusText}`);

    if (value.response?.data) {
      parts.push(String(value.response.data).slice(0, 1000));
    }

    if (parts.length > 0) return parts.join(" | ");

    try {
      return JSON.stringify(value).slice(0, 1500);
    } catch (e) {
      return "unknown_error_object";
    }
  }

  return String(value);
}

function detectStatusCode(text, json) {
  const direct =
    json.status ||
    json.statusCode ||
    json.error_status_code ||
    json.error?.status ||
    json.error?.statusCode ||
    json.error?.response?.status ||
    json.error_message?.status ||
    json.error_message?.statusCode ||
    json.error_message?.response?.status;

  if (direct) return String(direct);

  const match = String(text).match(/\b(400|401|403|404|408|409|429|500|502|503|504)\b/);
  return match ? match[1] : "unknown_status";
}

function buildShortMessage(rawText, statusCode) {
  const plain = stripHtml(rawText);
  const lower = plain.toLowerCase();

  if (statusCode === "403" && lower.includes("cloudfront")) {
    return "403 - Request blocked by CloudFront";
  }

  if (statusCode === "403" && lower.includes("request blocked")) {
    return "403 - Request blocked";
  }

  if (lower.includes("the request could not be satisfied")) {
    return `${statusCode} - The request could not be satisfied`;
  }

  if (lower.includes("too many requests") || statusCode === "429") {
    return `${statusCode} - Too many requests`;
  }

  if (lower.includes("not found") || statusCode === "404") {
    return `${statusCode} - Not found`;
  }

  if (lower.includes("timeout") || lower.includes("timed out")) {
    return `${statusCode} - Request timeout`;
  }

  if (lower.includes("axioserror")) {
    return `${statusCode} - Axios request failed`;
  }

  return `${statusCode} - ${plain.slice(0, 160)}`;
}

