function detectFailedPrimaryTargetAlternativeEntity(text) {
  const t = normalize(text);

  const hasFailedPrimaryCue = hasAny(t, [
    /\bnach\b.*\b(scheitern|scheitert|scheiterte|geplatzt|platzt|absage|aus)\b/,
    /\bdeal\b.*\b(geplatzt|platzt|scheitert|scheiterte|aus)\b/,
    /\bwechsel\b.*\b(geplatzt|platzt|scheitert|scheiterte|aus)\b/,
    /\bpoker\b.*\b(geplatzt|platzt|scheitert|scheiterte|aus)\b/
  ]);

  const hasAlternativeCue = hasAny(t, [
    /\bplan\s*b\b/,
    /\balternative\b/,
    /\bersatz\b/,
    /\boption\b/,
    /\bneue[nrsm]?\s+(fluegelspieler|offensivspieler|angreifer|stuermer|verteidiger|kandidat|option|loesung)\b/,
    /\bnimmt\b.*\bins visier\b/,
    /\bprueft\b.*\b(option|alternative|kandidat|spieler|profi|juwel|star)\b/,
    /\bbedient sich\b/,
    /\bschaut bei\b/
  ]);

  if (!hasFailedPrimaryCue || !hasAlternativeCue) return "";

  const transferCandidates = entityPatterns.filter(e => e.type === "transfer_candidate");
  const matched = transferCandidates.filter(candidate => candidate.patterns.some(pattern => pattern.test(t)));

  if (!matched.length) return "failed_primary_alternative";

  return `${matched[0].key}_alternative`;
}

function detectTransferCandidateEntity(text) {
  const t = normalize(text);

  if (!hasTransferOrPlayerTopic(t)) return "";

  const transferCandidates = entityPatterns.filter(e => e.type === "transfer_candidate");
  const matched = transferCandidates.filter(candidate => candidate.patterns.some(pattern => pattern.test(t)));

  if (!matched.length) return "";

  const alternativeTrigger = detectFailedPrimaryTargetAlternativeEntity(t);

  if (alternativeTrigger) {
    const triggerBase = alternativeTrigger.replace(/_alternative$/, "");
    const nonTrigger = matched.find(candidate => candidate.key !== triggerBase);

    if (nonTrigger) return nonTrigger.key;

    return alternativeTrigger;
  }

  return matched[0].key;
}

function detectKnownEntity(text) {
  const t = normalize(text);

  for (const entity of entityPatterns) {
    if (entity.patterns.some(pattern => pattern.test(t))) {
      return entity.key;
    }
  }

  return "";
}

function detectDynamicEntity(rawText) {
  const raw = String(rawText || "");
  const norm = normalize(raw);

  if (!hasTransferOrPlayerTopic(norm) && !hasAny(norm, [/\bspieler\b/, /\bprofi\b/, /\btalent\b/, /\bstar\b/])) {
    return "";
  }

  const blockedLastNames = new Set([
    "schalke", "gelsenkirchen", "munich", "inside", "sport", "bild", "kicker", "sky",
    "bundesliga", "champions", "league", "europa", "premier", "deutschland",
    "frankreich", "spanien", "italien", "england", "barcelona", "liverpool",
    "arsenal", "chelsea", "dortmund", "leverkusen", "juventus", "inter",
    "milan", "psg", "paris", "madrid", "transfer", "wechsel", "spieler",
    "profi", "star", "talent", "trainer", "kandidat", "wunschziel",
    "transferziel", "option", "alternative", "zukunft", "offen", "plan",
    "deal", "poker", "boss", "insider", "bericht", "berichte"
  ]);

  const nameRegex = /\b([A-ZÄÖÜ][a-zäöüßéèêëáàâíìîóòôúùûçñ'’-]{2,})\s+([A-ZÄÖÜ][a-zäöüßéèêëáàâíìîóòôúùûçñ'’-]{2,})\b/g;

  const candidates = [];
  let match;

  while ((match = nameRegex.exec(raw)) !== null) {
    const lastKey = normalizeKey(match[2]);
    const fullKey = normalizeKey(`${match[1]} ${match[2]}`);

    if (!lastKey || lastKey.length < 4) continue;
    if (blockedLastNames.has(lastKey)) continue;
    if (["fc_schalke", "schalke_gelsenkirchen", "champions_league", "europa_league"].includes(fullKey)) continue;

    candidates.push({ key: lastKey, index: match.index });
  }

  if (!candidates.length) return "";

  const preferred = candidates.find(c => {
    const around = normalize(raw.slice(Math.max(0, c.index - 160), c.index + 220));
    return hasTransferOrPlayerTopic(around) || hasAny(around, [/\bspieler\b/, /\bprofi\b/, /\btalent\b/, /\bstar\b/]);
  });

  return (preferred || candidates[0]).key;
}

function detectEntity(text, rawText) {
  const t = normalize(text);
  const transferCandidate = detectTransferCandidateEntity(t);

  if (transferCandidate) return transferCandidate;

  let known = detectKnownEntity(t);
  const dynamic = detectDynamicEntity(rawText || text);

  // (kein Adjektiv-Kollisions-Guard noetig fuer S04-Kader)

  if (known) return known;
  if (dynamic) return dynamic;

  return "";
}

function detectSpeakerEntity(text, mainEntity) {
  const t = normalize(text);

  const possibleSpeakers = entityPatterns.filter(e =>
    ["schalke_player", "former_schalke_player", "staff", "legend", "external_person"].includes(e.type)
  );

  for (const speaker of possibleSpeakers) {
    if (speaker.key === mainEntity) continue;

    if (speaker.patterns.some(pattern => pattern.test(t))) {
      if (hasAny(t, [
        /\bstichelt\b/,
        /\bspottet\b/,
