        /\bfindet\b/,
        /\bnennt\b/,
        /\bueber\b/,
        /\bfrage\b/,
        /\bordnet\b/
      ])) {
        return speaker.key;
      }
    }
  }

  return "";
}

function detectAllEntities(text, allowedTypes) {
  const t = normalize(text);
  const result = [];

  for (const entity of entityPatterns) {
    if (allowedTypes && allowedTypes.length && !allowedTypes.includes(entity.type)) continue;
    if (entity.patterns.some(pattern => pattern.test(t))) result.push(entity.key);
  }

  return uniqueList(result);
}

function detectEntityGroup(text, primaryEntity) {
  const entities = detectAllEntities(text, [
    "schalke_player",
    "former_schalke_player",
    "transfer_candidate",
    "staff",
    "legend"
  ]);

  if (primaryEntity && !entities.includes(primaryEntity)) {
    entities.unshift(primaryEntity);
  }

  const playerLike = entities.filter(entity => isPlayerEntity(entity) || isFormerS04PlayerEntity(entity));

  if (playerLike.length >= 2) return playerLike.slice(0, 3).sort().join("_");
  if (entities.length >= 2) return entities.slice(0, 3).sort().join("_");

  return primaryEntity || entities[0] || "";
}

function detectTeamUnit(text) {
  const t = normalize(text);

  if (hasAny(t, [/\bmittelfeld\b/, /\bzentrum\b/, /\bsechser\b/, /\bachter\b/])) return "midfield";
  if (hasAny(t, [/\bsturm\b/, /\boffensive\b/, /\bangriff\b/, /\bangreifer\b/, /\bfluegel\b/, /\bfluegelspieler\b/, /\baussenstuermer\b/])) return "attack";
  if (hasAny(t, [/\babwehr\b/, /\bdefensive\b/, /\bverteidigung\b/, /\binnenverteidigung\b/, /\bverteidiger\b/])) return "defense";
  if (hasAny(t, [/\btorwart\b/, /\bkeeper\b/, /\bschlussmann\b/])) return "goalkeeper";
  if (hasAny(t, [/\bteam\b/, /\bmannschaft\b/, /\belf\b/, /\bblock\b/, /\bschalke[-\s]?stars\b/])) return "team";

  return "";
}

function detectAwardType(text) {
  const t = normalize(text);

  if (hasAny(t, [/\bballon[-\s]?d\s?or\b/, /\bballon d or\b/, /\bballon dor\b/, /\bweltfussballer\b/])) return "ballon_dor";
  if (hasAny(t, [/\besm[-\s]?elf\b/, /\belf des monats\b/, /\bteam des monats\b/, /\belf des mai\b/])) return "team_of_month";
  if (hasAny(t, [/\belf der saison\b/, /\bteam der saison\b/, /\bucl[-\s]?elf\b/, /\buefa[-\s]?elf\b/, /\bchampions[-\s]?league[-\s]?elf\b/, /\bvdv[-\s]?elf\b/])) return "team_of_season";
  if (hasAny(t, [/\bspieler der saison\b/, /\bbester offensivspieler\b/, /\bbester spieler\b/, /\bplayer of the season\b/, /\bspieler des jahres\b/, /\bvdv[-\s]?auszeichnung\b/, /\bvdv[-\s]?wahl\b/])) return "player_of_season";
  if (hasAny(t, [/\bgoldener schuh\b/, /\bgoldenen schuh\b/, /\bgolden shoe\b/])) return "golden_shoe";
  if (hasAny(t, [/\bgeehrt\b/, /\bausgezeichnet\b/, /\bauszeichnung\b/, /\bpreis\b/, /\btrophaee\b/, /\baward\b/, /\bwahl\b/, /\bgewaehlt\b/, /\bfavorit\b/, /\bfavoriten\b/])) return "award_general";

  return "";
}

function detectRatingType(text) {
  const t = normalize(text);

  if (!hasAny(t, [/\bnoten\b/, /\bnote\b/, /\beinzelkritik\b/, /\bspielerbewertung\b/, /\bbewertet\b/, /\bbewertung\b/, /\bzeugnis\b/])) return "";

  const unit = detectTeamUnit(t);
  return unit ? `${unit}_rating` : "player_rating";
}

function detectTransferProfile(text) {
  const t = normalize(text);

  if (hasAny(t, [/\bkaraman[-\s]?backup\b/, /\bbackup fuer karaman\b/, /\bersatz fuer karaman\b/, /\bkaraman[-\s]?ersatz\b/, /\bkaraman[-\s]?alternative\b/])) return "karaman_backup";
  if (hasAny(t, [/\bstuermer[-\s]?backup\b/, /\bstuermer\b/, /\bangreifer\b/, /\bmittelstuermer\b/, /\bneuner\b/, /\b9er\b/])) return "striker";
  if (hasAny(t, [/\binnenverteidiger\b/, /\babwehrchef\b/, /\bzentraler verteidiger\b/])) return "center_back";
  if (hasAny(t, [/\blinksverteidiger\b/, /\blv\b/])) return "left_back";
  if (hasAny(t, [/\brechtsverteidiger\b/, /\brv\b/])) return "right_back";
  if (hasAny(t, [/\bverteidiger\b/, /\babwehrspieler\b/, /\bdefensivspieler\b/])) return "defender";
  if (hasAny(t, [/\bsechser\b/, /\b6er\b/, /\bdefensives mittelfeld\b/, /\bmittelfeldspieler\b/, /\bzentrum\b/])) return "midfielder";
  if (hasAny(t, [/\bfluegelspieler\b/, /\bwinger\b/, /\baussenstuermer\b/, /\boffensivspieler\b/, /\boffensiv[-\s]?juwel\b/, /\boffensive[-\s]?deal\b/, /\boffensive[-\s]?option\b/])) return "winger";
  if (hasAny(t, [/\btorwart\b/, /\bkeeper\b/, /\bschlussmann\b/])) return "goalkeeper";
  if (hasAny(t, [/\btop[-\s]?talent\b/, /\bmegatalent\b/, /\bjuwel\b/, /\btalent\b/])) return "talent";

  return "";
}

function detectTransferDevelopmentDetail(text) {
  const t = normalize(text);

  if (hasAny(t, [
    /\boffiziell\b/,
    /\bfix\b/,
    /\bperfekt\b/,
    /\bwende perfekt\b/,
    /\bdeal perfekt\b/,
    /\btransfer perfekt\b/,
    /\bpraesentiert\b/,
    /\bunterschreibt\b/,
    /\bwechselt zu\b/,
    /\bwechselt nach\b/,
    /\bverpflichtet\b/,
    /\bverstaerkt\b/,
    /\bschliesst sich\b/,
    /\btransfer ist durch\b/,
    /\bdeal ist durch\b/
  ])) return "completed";

  if (hasAny(t, [
    /\bausgestochen\b/,
    /\bgeht leer aus\b/,
    /\bging leer aus\b/,
    /\bhat das nachsehen\b/,
    /\bchancenlos\b/,
    /\baus dem rennen\b/,
    /\bschalke aus\b/,
    /\bkein .* wechsel nach (gelsenkirchen|schalke)\b/
  ])) return "schalke_lost";

  if (hasAny(t, [
    /\babsage\b/,
    /\bsagt ab\b/,
    /\bkein wechsel\b/,
    /\bwechselt nicht\b/,
    /\bscheitert\b/,
    /\bscheiterte\b/,
    /\bgescheitert\w*\b/,
    /\bplatzt\b/,
    /\bgeplatzt\b/,
    /\brueckt ab\b/
  ])) return "rejection";

  if (hasAny(t, [
    /\bwinkt\s+ab\b/,
    /\bblockt\s+ab\b/,
    /\blehnt\s+ab\b/,
    /\bwill\s+.*\bnicht\s+abgeben\b/,
    /\bwill\s+.*\bhalten\b/,
    /\bhaelt\s+.*\bfest\b/,
    /\bpocht\s+auf\b/,
    /\bnicht\s+zu\s+haben\b/,
    /\bunverkaeuflich\b/,
    /\bnicht\s+zu\s+verkaufen\b/,
    /\bkeine\s+freigabe\b/,
    /\bliegt\s+vorerst\s+auf\s+eis\b/,
    /\bliegt\s+auf\s+eis\b/
  ])) return "club_blocks";

  if (hasAny(t, [
    /\bmuendliche einigung\b/,
    /\bmuendlich einig\b/,
    /\beinig(?:ung)?\b.*\b(spieler|profi|kandidat|star)\b/,
    /\b(spieler|profi|kandidat|star)\b.*\beinig(?:ung)?\b/,
    /\bpersoenliche bedingungen\b/,
    /\bwill zu schalke\b/,
    /\bwill nach gelsenkirchen\b/,
    /\bsagt schalke zu\b/,
    /\bsagt zu\b/,
    /\bhat zugesagt\b/,
    /\bgruenes licht\b/,
    /\boffen fuer schalke\b/,
    /\btendiert zu schalke\b/,
    /\bpraeferiert schalke\b/
  ])) return "player_greenlight";

  if (hasAny(t, [
    /\bschalke und .* einig\b/,
    /\beinig\b.*\b(psv|verein|klub|club)\b/,
    /\bvereinbarung\b.*\b(psv|verein|klub|club)\b/,
    /\bvor dem abschluss\b/,
    /\bauf der zielgeraden\b/
  ])) return "club_agreement";

  if (hasAny(t, [
    /\bangebot\b.*\beingereicht\b/,
    /\bofferte\b.*\beingereicht\b/,
    /\bgebot\b.*\beingereicht\b/,
    /\blegt\b.*\bangebot\b.*\bvor\b/,
    /\berstes angebot\b.*\bvor\b/
  ])) return "offer_submitted";

  if (hasAny(t, [
    /\bangebot\b.*\bgeplant\b/,
    /\berstes angebot\b.*\bgeplant\b/,
    /\bbereitet\b.*\bangebot\b.*\bvor\b/,
    /\bgebot\b.*\bgeplant\b/
  ])) return "offer_planned";

  if (hasAny(t, [/\bangebot\b/, /\bofferte\b/, /\bbietet\b/, /\berstes gebot\b/, /\bneues gebot\b/, /\babloseangebot\b/])) return "offer";

  if (hasAny(t, [/\bhandgeld\b/, /\bausgleich\b/, /\babfindung\b/, /\bpaket\b/, /\bgesamtpaket\b/])) return "cost_package";

  if (hasAny(t, [
    /\brekordabloese\b/,
    /\babloseforderung\b/,
    /\bfordert\b.*\b(millionen|abloese|preis)\b/,
    /\bpreisschild\b/,
    /\bhohe abloese\b/,
    /\bablose offen\b/,
    /\bzu teuer\b/,
    /\bkosten bremsen\b/,
    /\bmuss mehr einplanen\b/,
    /\bguenstiger\b/,
    /\bmarktwert\b/
  ])) return "price";

  if (hasAny(t, [
    /\bverhandlungen\b/,
    /\bverhandelt\b/,
    /\bgespraeche\b/,
    /\bkontakt\b/,
    /\btreffen\b/,
    /\bnaeher\b/,
    /\bkommen naeher\b/,
    /\bdeal\b.*\bfinalisiert\b/,
    /\btransferpoker\b.*\bfort\b/
  ])) return "talks";

  if (hasAny(t, [
    /\bdeadline\b/,
    /\bfrist\b/,
    /\bultimatum\b/,
    /\bentscheidung\b/,
    /\bentscheidet\b/,
    /\bentscheidet sich\b/,
