    /\bschnell(?:en|er|e)?\b.*\bdeal\b/,
    /\btempo\b.*\berhoeht\b/,
    /\bsteigt aus\b/,
    /\blegt sich fest\b/
  ])) return "decision_timeline";

  if (hasAny(t, [
    /\bplan\s*b\b/,
    /\balternative\b/,
    /\boption\b/,
    /\bnach\b.*\b(scheitern|geplatzt|absage|aus)\b/,
    /\bneue[nrsm]?\s+(fluegelspieler|offensivspieler|angreifer|stuermer|verteidiger|kandidat|option|loesung)\b/
  ])) return "alternative_search";

  return "interest";
}

function detectTransferPhase(text) {
  const development = detectTransferDevelopmentDetail(text);

  if (development === "completed") return "completed";
  if (development === "schalke_lost") return "schalke_lost";
  if (development === "rejection") return "rejection";
  if (development === "club_blocks") return "club_blocks";
  if (development === "player_greenlight") return "player_greenlight";
  if (["offer_submitted", "offer_planned", "offer"].includes(development)) return "offer";
  if (["club_agreement", "talks"].includes(development)) return "talks";
  if (["cost_package", "price"].includes(development)) return "price";
  if (development === "decision_timeline") return "decision";
  if (development === "alternative_search") return "club_interest";

  return "general";
}

function normalizeTransferPhaseForDuplicates(phase, text) {
  const t = normalize(text);
  const p = String(phase || "general");

  if (["completed", "schalke_lost", "rejection", "club_blocks", "player_greenlight", "offer", "talks", "price", "decision"].includes(p)) {
    return p;
  }

  if (
    ["club_interest", "general"].includes(p) ||
    hasAny(t, [/\binteresse\b/, /\binteressiert\b/, /\bbeobachtet\b/, /\bscoutet\b/, /\bprueft\b/, /\bkandidat\b/, /\bwunschziel\b/, /\btransferziel\b/, /\boption\b/, /\balternative\b/, /\bpoker\b/, /\bmitbieten\b/])
  ) {
    return "interest";
  }

  return p || "general";
}

function detectTransferSubangle(text, entity, opponent, speaker) {
  const t = normalize(text);
  const phase = detectTransferPhase(t);
  const normalizedPhase = normalizeTransferPhaseForDuplicates(phase, t);
  const development = detectTransferDevelopmentDetail(t);

  const destination = opponent && !["deutschland", "dfb"].includes(opponent) ? opponent : "";

  const playerExplanation = hasAny(t, [
    /\bspricht ueber schalke\b/,
    /\bspricht ueber .* wechsel\b/,
    /\bspricht ueber .* transfer\b/,
    /\bwarum\b.*\bwechsel\b.*\b(scheiterte|scheitert|platzte|geplatzt)\b/,
    /\bwechsel nach (gelsenkirchen|schalke)\b.*\b(scheiterte|scheitert|platzte|geplatzt)\b/,
    /\berklaert\b.*\b(scheitern|absage|wechsel|transfer)\b/,
    /\bbegruendet\b.*\b(absage|wechsel|transfer)\b/
  ]);

  if (playerExplanation) {
    return {
      subangle: "player_explanation_failed_schalke_move",
      stage: "player_explanation",
      stage_rank: 86,
      detail: "player_explanation"
    };
  }

  const thirdPartyReaction = hasAny(t, [
    /\bstichelt\b/,
    /\bspottet\b/,
    /\bseitenhieb\b/,
    /\breagiert\b/,
    /\bkontert\b/,
    /\bkommentiert\b/,
    /\bfindet klare worte\b/,
    /\bmeint\b/,
    /\bsagt\b.*\b(absage|wechsel|transfer|entscheidung)\b/,
    /\bspricht\b.*\b(absage|wechsel|transfer|entscheidung)\b/
  ]) && Boolean(speaker);

  if (thirdPartyReaction) {
    return {
      subangle: speaker ? `reaction_${speaker}` : "reaction",
      stage: "reaction",
      stage_rank: 85,
      detail: "third_party_reaction"
    };
  }

  const analysisLost = hasAny(t, [
    /\bwar im rennen\b.*\b(chancenlos|letztlich chancenlos|keine chance)\b/,
    /\bchancenlos\b/,
    /\bhatte keine chance\b/,
    /\bwarum\b.*\bschalke\b.*\b(leer aus|scheitert|scheiterte|chancenlos)\b/,
    /\bhintergruende\b/,
    /\bgruende\b/,
    /\beinordnung\b/,
    /\banalyse\b/
  ]);

  if (analysisLost && (phase === "schalke_lost" || hasS04ClubText(t))) {
    return {
      subangle: "schalke_lost_analysis",
      stage: "schalke_lost_analysis",
      stage_rank: 75,
      detail: "analysis_schalke_lost"
    };
  }

  if (development === "alternative_search" || String(entity || "").endsWith("_alternative")) {
    return {
      subangle: entity ? `${entity}_alternative_search` : "alternative_search",
      stage: "interest",
      stage_rank: 20,
      detail: "alternative_after_failed_primary_target"
    };
  }

  const mapping = {
    completed: { subangle: destination ? `completed_${destination}` : "completed", stage: "completed", stage_rank: 80 },
    schalke_lost: { subangle: destination ? `schalke_lost_${destination}` : "schalke_lost", stage: "schalke_lost", stage_rank: 65 },
    rejection: { subangle: destination ? `rejection_${destination}` : "rejection", stage: "rejection", stage_rank: 60 },
    club_blocks: { subangle: destination ? `club_blocks_${destination}` : "club_blocks", stage: "club_blocks", stage_rank: 58 },
    club_agreement: { subangle: destination ? `club_agreement_${destination}` : "club_agreement", stage: "talks", stage_rank: 48 },
    player_greenlight: { subangle: "player_greenlight", stage: "player_greenlight", stage_rank: 45 },
    offer_submitted: { subangle: "offer_submitted", stage: "offer", stage_rank: 52 },
    offer_planned: { subangle: "offer_planned", stage: "offer", stage_rank: 50 },
    offer: { subangle: "offer", stage: "offer", stage_rank: 50 },
    cost_package: { subangle: "cost_package", stage: "price", stage_rank: 38 },
    price: { subangle: "price", stage: "price", stage_rank: 35 },
    decision_timeline: { subangle: "decision_timeline", stage: "decision", stage_rank: 32 },
    talks: { subangle: destination ? `talks_${destination}` : "talks", stage: "talks", stage_rank: 40 }
  };

  if (mapping[development]) return Object.assign({}, mapping[development], { detail: development });

  if (normalizedPhase === "talks") return { subangle: destination ? `talks_${destination}` : "talks", stage: "talks", stage_rank: 40, detail: phase };

  return { subangle: destination ? `interest_${destination}` : "interest", stage: "interest", stage_rank: 20, detail: phase };
}

function detectFuturePhase(text) {
  const t = normalize(text);

  if (hasAny(t, [/\bverkauf\b/, /\bverkaufen\b/, /\bverkaufsliste\b/, /\bstreichliste\b/, /\bpreisschild\b/, /\babgangskandidat\b/, /\bverkaufskandidat\b/])) return "sale";
  if (hasAny(t, [/\babgang\b/, /\babschied\b/, /\bverlaesst\b/, /\bwechsel\b/, /\bvor abschied\b/, /\bvor abgang\b/, /\bneuer klub\b/, /\bverbleib\b/])) return "exit";
  if (hasAny(t, [/\bnicht\s+zu\s+verkaufen\b/, /\bunverkaeuflich\b/, /\bkeine\s+freigabe\b/, /\bbleibt\b/, /\bbleiben\b/, /\bnicht verlassen\b/, /\bwill .* nicht verlassen\b/, /\bsoll bleiben\b/, /\bstellt sich quer\b/])) return "retention";
  if (hasAny(t, [/\bvertrag\b/, /\bverlaengert\b/, /\bverlaengerung\b/, /\bvertragsverlaengerung\b/])) return "contract";
  if (hasAny(t, [/\bleihe\b/, /\bausleihe\b/, /\bkaufoption\b/, /\brueckkehr\b/, /\brueckkehrer\b/])) return "loan";
  if (hasAny(t, [/\brolle\b/, /\bsituation\b/, /\bmissverstaendnis\b/, /\benttaeuschung\b/, /\bproblem\b/, /\bkaum einsatzzeit\b/, /\breservist\b/])) return "role";
  if (hasAny(t, [/\bgehalt\b/, /\bmillionenverlust\b/, /\bteuer\b/, /\bkosten\b/, /\bmarktwert\b/])) return "finance";

  return "general";
}

function detectInjuryPhase(text) {
  const t = normalize(text);

  const hasInjuryContext = hasAny(t, [
    /\bverletz/,
    /\bausfall\b/,
    /\bfaellt aus\b/,
    /\bfehlt\b/,
    /\bverpasst\b/,
    /\bangeschlagen\b/,
    /\bfraglich\b/,
    /\bwackelt\b/,
    /\bdiagnose\b/,
    /\btraining\b/,
    /\bcomeback\b/,
    /\brueckkehr\b/
  ]);

  const hasNationalContext = hasAny(t, [
    /\bdfb\b/,
    /\bnationalmannschaft\b/,
    /\bbundestrainer\b/,
    /\bnagelsmann\b/,
    /\bwm\b/,
    /\bem\b/,
    /\blaenderspiel\b/,
    /\btestspiel\b/,
    /\busa\b/,
    /\bkanada\b/,
    /\bfrankreich\b/,
    /\bdeutschland\b/
  ]);

  const hasAbsenceOrDelay = hasAny(t, [
    /\bfaellt aus\b/,
    /\bausfall\b/,
    /\bfehlt\b/,
    /\bverpasst\b/,
    /\bnicht dabei\b/,
    /\bcomeback\b.*\b(verzoegert|offen|wackelt)\b/,
    /\brueckkehr\b.*\b(verzoegert|offen|wackelt)\b/,
    /\bbaumann\b.*\b(dfb|tor|startelf|rueckt)\b/,
    /\brueckt\b.*\bdfb[-\s]?tor\b/
  ]);

  if (hasInjuryContext && hasNationalContext && hasAbsenceOrDelay) {
    return "national_absence";
  }

  if (hasInjuryContext && hasAny(t, [
    /\bmeldet\s+sich\b/,
    /\baeussert\s+sich\b/,
    /\bspricht\b/,
    /\bpostet\b/,
    /\breagiert\b/,
    /\btraurig\b/,
    /\benttaeuscht\b/,
    /\bit\s+tut\s+weh\b/,
    /\bes\s+tut\s+weh\b/,
    /\bbitter\s+enttaeuscht\b/
  ])) {
    return "personal_reaction";
  }

  if (hasInjuryContext && hasAny(t, [
    /\bexperte\b/,
    /\btv[-\s]?experte\b/,
    /\bmatthaeus\b/,
    /\breif\b/,
    /\bfordert\b/,
    /\bsieht\b.*\bkopf\b/,
    /\bkopf\s+gefordert\b/,
    /\bordnet\b.*\bein\b/,
    /\beinschaetzung\b/
  ])) {
    return "external_reaction";
  }

  if (hasAny(t, [/\bdiagnose\b/, /\bbefund\b/, /\buntersuchung\b/, /\bmrt\b/, /\bmuskelverletzung\b/, /\bfaserriss\b/, /\bbaenderriss\b/, /\boperation\b/, /\bop\b/])) return "diagnose";
  if (hasAny(t, [/\bfaellt aus\b/, /\bausfall\b/, /\bfehlt\b/, /\bnicht dabei\b/, /\bverpasst\b/, /\bsperre\b/])) return "ausfall";
  if (hasAny(t, [/\bangeschlagen\b/, /\bfraglich\b/, /\bwackelt\b/, /\bzweifel\b/, /\btraining abgebrochen\b/, /\btraining verpasst\b/, /\bindividuell\b/, /\bbangt\b/, /\boffen\b/])) return "fraglich";
  if (hasAny(t, [/\bcomeback\b/, /\brueckkehr\b/, /\bzurueck\b/, /\btrainiert wieder\b/])) return "comeback";

  return "general";
}

function detectStatementAngle(text) {
