  if (hasAny(t, [/\bberater\b/, /\bberaterkosten\b/, /\bberaterhonorar\b/, /\bdfl[-\s]?bericht\b/, /\bprovision\b/])) return "beraterkosten";

  return "finance";
}

function detectClubEventType(text) {
