    /\btrainer\b/,
    /\bfunktion\b/,
    /\bposten\b/,
    /\bneuer job\b/
  ]);

  if (!legacyPerson && !hasLegacyContext) return "";
  if (!hasLegacyAngle && !hasLegacyContext) return "";

