function detectTopic(text, opponent, entity, speaker) {
  const t = normalize(text);

  const awardType = detectAwardType(t);
  const ratingType = detectRatingType(t);
  const clubStrategyType = detectClubStrategyType(t, entity);
  const socialBuzzType = detectClubSocialBuzzType(t);
  const staffSituationType = detectStaffSituationType(t, entity);
  const tournamentBenefitType = detectTournamentBenefitType(t);

  if (staffSituationType) return "staff_situation";
  if (tournamentBenefitType) return "tournament_benefit";
  if (detectMultisportType(t, entity)) return "schalke_multisport";
  if (detectS04AffinityType(t)) return "schalke_affinity";
  if (detectFanServiceType(t)) return "fan_service";
  if (hasS04ClubText(t) && detectClubEventType(t)) return "club_event";

  if (awardType && (hasS04ClubText(t) || entity || detectEntityGroup(t, entity))) return "award";
  if (ratingType && (hasS04ClubText(t) || entity || detectTeamUnit(t))) return "player_rating";
  if (clubStrategyType) return "club_strategy";
  if (socialBuzzType) return "club_social_buzz";

  if (hasAny(t, [/\bberater\b/, /\bberaterkosten\b/, /\bberaterhonorar\b/, /\bdfl[-\s]?bericht\b/, /\bprovision\b/, /\bgehalt\b/, /\bmarktwert\b/, /\babloese\b/, /\bpreisschild\b/, /\bmillionenverlust\b/])) return "finanzen";
  if (detectGovernanceContext(t, entity)) return "football_governance";
  if (detectLegacyType(t, entity)) return "schalke_legacy";
  if (detectDfbCurrentS04PlayerType(t, entity)) return "dfb_nationalteam";

  if (hasAny(t, [/\baufstellung\b/, /\bstartelf\b/, /\bstart-elf\b/, /\bso spielt\b/, /\bvoraussichtliche aufstellung\b/]) && (hasS04ClubText(t) || opponent)) return "aufstellung";
  if (hasAny(t, [/\blive im tv\b/, /\blivestream\b/, /\btv und stream\b/, /\buebertragung\b/, /\bwer zeigt\b/, /\bwo laeuft\b/])) return "tv_service";
  if (hasAny(t, [/\bschiedsrichter\b/, /\bschiri\b/, /\bvar\b/, /\belfmeter\b/, /\bfehlentscheidung\b/])) return "schiedsrichter";
  if (hasAny(t, [/\bverletz/, /\bausfall\b/, /\bfaellt aus\b/, /\bangeschlagen\b/, /\bfraglich\b/, /\bwackelt\b/, /\bfehlt\b/, /\boperation\b/, /\bcomeback\b/, /\breha\b/, /\bbangt\b/])) return "verletzung";

  if (hasTransferOrPlayerTopic(t)) {
    if (hasAny(t, [/\binteresse\b/, /\binteressiert\b/, /\bbeobachtet\b/, /\bscoutet\b/, /\bgeruecht\w*\b/, /\bkandidat\b/, /\boption\b/, /\balternative\b/, /\bprueft\b/, /\bpoker\b/, /\bmitbieten\b/, /\bim visier\b/, /\bauf dem zettel\b/])) {
      return "transfer_geruecht";
    }

    return "transfer";
  }

  if (hasAny(t, [/\bzukunft\b/, /\bbleibt\b/, /\bbleiben\b/, /\babschied\b/, /\bverlaengert\b/, /\bverlaengerung\b/, /\bvertrag\b/, /\bnicht verlassen\b/])) return "zukunft";
  if (hasAny(t, [/\bkader\b/, /\baufgebot\b/, /\brueckkehr\b/, /\bstartelf\b/, /\bnominiert\b/])) return "kader";
  if (
    hasAny(t, [/\binterview\b/, /\baussage\b/, /\bspricht ueber\b/, /\bwarnt\b/, /\blobt\b/, /\bschwaermt\b/, /\bspott\b/, /\bstichelt\b/]) ||
    (entity && speaker && hasAny(t, [/\bueber\b/, /\bfrage\b/, /\breaktion\b/, /\bsagt\b/, /\bspricht\b/, /\bmeint\b/, /\bfindet\b/]))
  ) return "aussage";

  if (hasAny(t, [/\bspielbericht\b/, /\bergebnis\b/, /\bendstand\b/, /\bsieg\b/, /\bniederlage\b/, /\bremis\b/]) && (hasS04ClubText(t) || opponent)) return "match";

  return "general";
}

function cleanWords(text) {
  const noise = new Set([
    "der", "die", "das", "ein", "eine", "einer", "einen", "einem",
    "und", "oder", "aber", "auch", "mit", "bei", "von", "vor", "nach",
    "zum", "zur", "auf", "fuer", "im", "am", "an", "aus", "des", "den",
    "dem", "ist", "sind", "war", "waren", "wird", "werden", "hat",
    "haben", "nicht", "mehr", "noch", "weiter", "wieder", "will", "soll",
    "kann", "steht", "zieht", "fc", "schalke", "gelsenkirchen", "s04",
    "bericht", "berichte", "news", "neuer", "neue", "neues", "plan",
    "offenbar", "wohl", "jetzt", "doch", "spiel", "partie", "duell",
    "gegen", "bundesliga", "champions", "league", "sommer", "heute",
    "live", "sport", "fussball", "artikel", "spieler", "star", "profi",
    "talent", "trainer", "boss", "wirklich", "poker", "deal"
  ]);

  return normalize(text)
    .split(" ")
    .map(w => normalizeKey(w))
    .filter(w => w.length >= 4)
    .filter(w => !noise.has(w))
    .map(w => {
      if (w === "karamans") return "karaman";
      if (w === "syllas") return "sylla";
      if (w === "konates") return "konate";
      if (w === "gordons") return "gordon";
      if (w === "browns") return "brown";
      if (w === "kroupis") return "kroupi";
      if (w.endsWith("s") && w.length > 6) return w.replace(/s$/, "");
      return w;
    })
    .filter(w => !noise.has(w));
}

