function detectStoryStage(text, topic, entity, opponent, transferSubangleInfo) {
  const t = normalize(text);
  const futurePhase = detectFuturePhase(t);
  const injuryPhase = detectInjuryPhase(t);

  if (topic === "transfer" || topic === "transfer_geruecht") {
    return {
      stage: transferSubangleInfo.stage,
      rank: transferSubangleInfo.stage_rank,
      detail: transferSubangleInfo.detail,
      is_hard_update: transferSubangleInfo.stage_rank >= 50
    };
  }

  if (topic === "staff_situation") {
    const staffType = detectStaffSituationType(t, entity);

    if (staffType === "deadline") return { stage: "staff_deadline", rank: getStageRank("staff_deadline"), detail: staffType, is_hard_update: true };
    if (staffType === "pressure") return { stage: "staff_pressure", rank: getStageRank("staff_pressure"), detail: staffType };

    return { stage: "staff_future_general", rank: getStageRank("staff_future_general"), detail: staffType || "general" };
  }

  if (topic === "tournament_benefit") {
    const tournamentType = detectTournamentBenefitType(t);

    if (tournamentType === "revenue") return { stage: "tournament_revenue", rank: getStageRank("tournament_revenue"), detail: tournamentType, is_hard_update: true };
    if (tournamentType === "participants") return { stage: "tournament_participants", rank: getStageRank("tournament_participants"), detail: tournamentType, is_hard_update: true };

    return { stage: "general", rank: getStageRank("general"), detail: tournamentType || "general" };
  }

  if (topic === "verletzung") {
    if (injuryPhase === "national_absence") return { stage: "injury_national_absence", rank: getStageRank("injury_national_absence"), detail: injuryPhase, is_hard_update: true };
    if (injuryPhase === "personal_reaction") return { stage: "injury_personal_reaction", rank: getStageRank("injury_personal_reaction"), detail: injuryPhase, is_hard_update: true };
    if (injuryPhase === "external_reaction") return { stage: "injury_external_reaction", rank: getStageRank("injury_external_reaction"), detail: injuryPhase, is_hard_update: true };
    if (injuryPhase === "diagnose") return { stage: "injury_diagnose", rank: getStageRank("injury_diagnose"), detail: injuryPhase, is_hard_update: true };
    if (injuryPhase === "ausfall") return { stage: "injury_ausfall", rank: getStageRank("injury_ausfall"), detail: injuryPhase, is_hard_update: true };
    if (injuryPhase === "comeback") return { stage: "injury_comeback", rank: getStageRank("injury_comeback"), detail: injuryPhase, is_hard_update: true };
    if (injuryPhase === "fraglich") return { stage: "injury_fraglich", rank: getStageRank("injury_fraglich"), detail: injuryPhase };

    return { stage: "general", rank: getStageRank("general"), detail: injuryPhase };
  }

  if (topic === "zukunft" || (entity && isS04PlayerEntity(entity) && hasAny(t, [/\bzukunft\b/, /\bbleibt\b/, /\babgang\b/, /\babschied\b/, /\bvertrag\b/]))) {
    const stage = futurePhase && futurePhase !== "general" ? `future_${futurePhase}` : "future_general";
    return { stage, rank: getStageRank(stage), detail: futurePhase };
  }

  if (topic === "dfb_nationalteam") {
    const dfbType = detectDfbCurrentS04PlayerType(t, entity);
    const dfbCluster = detectDfbStoryCluster(t, entity);

    if (dfbType === "kader") return { stage: "dfb_kader", rank: getStageRank("dfb_kader"), detail: dfbCluster || dfbType, is_hard_update: true };
    if (dfbType === "startelf") return { stage: "dfb_event", rank: getStageRank("dfb_event"), detail: dfbCluster || dfbType, is_hard_update: true };
    if (dfbType === "return") return { stage: "dfb_return", rank: getStageRank("dfb_return"), detail: dfbCluster || dfbType, is_hard_update: true };
    if (dfbType === "performance") return { stage: "dfb_event", rank: getStageRank("dfb_event"), detail: dfbCluster || dfbType };
    if (dfbType === "statement") return { stage: "dfb_event", rank: getStageRank("dfb_event"), detail: dfbCluster || dfbType };

    return { stage: "dfb_event", rank: getStageRank("dfb_event"), detail: dfbCluster || dfbType || "general" };
  }

  if (topic === "award") return { stage: "award_general", rank: getStageRank("award_general"), detail: detectAwardType(t) || "award" };
  if (topic === "player_rating") return { stage: "rating_general", rank: getStageRank("rating_general"), detail: detectRatingType(t) || "rating" };
  if (topic === "club_strategy") return { stage: "club_strategy_general", rank: getStageRank("club_strategy_general"), detail: detectClubStrategyType(t, entity) || "strategy" };
  if (topic === "club_social_buzz") return { stage: "social_buzz_general", rank: getStageRank("social_buzz_general"), detail: detectClubSocialBuzzType(t) || "social_buzz" };

  if (["schalke_affinity", "schalke_legacy", "football_governance", "schalke_multisport"].includes(topic)) {
    return { stage: "general", rank: getStageRank("general"), detail: topic };
  }

  if (["aufstellung", "tv_service", "schiedsrichter", "match"].includes(topic)) {
    if (hasAny(t, [/\bspielbericht\b/, /\bendstand\b/, /\babpfiff\b/, /\bsieg\b/, /\bniederlage\b/, /\b\d+\s*:\s*\d+\b/])) {
      return { stage: "match_result", rank: getStageRank("match_result"), detail: "result" };
    }

    if (hasAny(t, [/\breaktion\b/, /\bstimmen\b/, /\bpressestimmen\b/, /\banalyse\b/, /\bnach dem spiel\b/])) {
      return { stage: "match_reaction", rank: getStageRank("match_reaction"), detail: "reaction" };
    }

    return { stage: "match_preview", rank: getStageRank("match_preview"), detail: "preview" };
  }

  if (detectHardUpdateSignal(t)) {
    return { stage: "aftermath", rank: getStageRank("aftermath"), detail: "hard_update_signal", is_hard_update: true };
  }

  return { stage: "general", rank: getStageRank("general"), detail: "general" };
}

function buildStoryThreadKey(topic, entity, opponent, transferProfile, words, extras) {
  const parts = [];
  const entityGroup = extras.entityGroup;
  const teamUnit = extras.teamUnit;
  const awardType = extras.awardType;
  const clubStrategyType = extras.clubStrategyType;
  const dfbMatchOpponent = extras.dfbMatchOpponent;
  const socialBuzzType = extras.socialBuzzType;
  const genericSourceClub = extras.genericSourceClub;
  const tournamentBenefitType = extras.tournamentBenefitType;

  if (topic === "transfer" || topic === "transfer_geruecht") {
    parts.push("transfer");

    if (entity && isPlayerEntity(entity)) {
      parts.push(entity);
    } else if (genericSourceClub && transferProfile) {
      parts.push(genericSourceClub, transferProfile);
    } else if (transferProfile) {
      parts.push(transferProfile);
    } else {
      parts.push(words.slice(0, 2).join("_"));
    }

    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "staff_situation") {
    parts.push("staff_situation", entity || "staff");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "tournament_benefit") {
    parts.push("tournament_benefit", tournamentBenefitType || "general");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "dfb_nationalteam") {
    parts.push("dfb", entity || entityGroup || "schalke_entity", dfbMatchOpponent || "general");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "award") {
    parts.push("award", entityGroup || entity || teamUnit || "club", awardType || "general");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "player_rating") {
    parts.push("rating", teamUnit || entityGroup || entity || "team");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "club_strategy") {
    parts.push("club_strategy", entity && isS04StaffEntity(entity) ? entity : "club", clubStrategyType || "general");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "club_social_buzz") {
    parts.push("club_social_buzz", socialBuzzType || "general");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "zukunft") {
    parts.push("zukunft", entity || words.slice(0, 2).join("_"));
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (topic === "verletzung") {
    parts.push("verletzung", entity && isPlayerEntity(entity) ? entity : "team");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (["aufstellung", "tv_service", "schiedsrichter", "match"].includes(topic)) {
    parts.push(topic, opponent || "general");
    return parts.map(normalizeKey).filter(Boolean).join("_");
  }

  if (entity) parts.push(topic || "general", entity);
  else if (opponent) parts.push(topic || "general", opponent);
  else parts.push(topic || "general", words.slice(0, 3).join("_"));

  return parts.map(normalizeKey).filter(Boolean).join("_");
}

function buildFingerprintParts(params) {
  const topic = params.topic;
  const entity = params.entity;
  const opponent = params.opponent;
  const speaker = params.speaker;
  const transferProfile = params.transferProfile;
  const transferSubangle = params.transferSubangle;
  const futurePhase = params.futurePhase;
  const injuryPhase = params.injuryPhase;
  const statementAngle = params.statementAngle;
  const financePhase = params.financePhase;
  const clubEventType = params.clubEventType;
  const clubEventProduct = params.clubEventProduct;
  const fanServiceType = params.fanServiceType;
  const legacyType = params.legacyType;
  const dfbType = params.dfbType;
  const affinityType = params.affinityType;
  const multisportType = params.multisportType;
  const awardType = params.awardType;
  const ratingType = params.ratingType;
  const teamUnit = params.teamUnit;
  const entityGroup = params.entityGroup;
  const clubStrategyType = params.clubStrategyType;
  const dfbCluster = params.dfbCluster;
  const socialBuzzType = params.socialBuzzType;
  const genericSourceClub = params.genericSourceClub;
  const staffSituationType = params.staffSituationType;
  const tournamentBenefitType = params.tournamentBenefitType;
  const words = params.words;

  let parts = [];

  if (topic === "transfer" || topic === "transfer_geruecht") {
    parts = ["transfer"];

    if (entity && isPlayerEntity(entity)) {
      parts.push(entity);
    } else if (entity) {
      parts.push(entity);
    } else if (genericSourceClub && transferProfile) {
      parts.push(genericSourceClub, transferProfile);
    } else if (genericSourceClub) {
      parts.push(genericSourceClub);
    } else if (transferProfile) {
      parts.push(transferProfile);
    } else {
      parts.push.apply(parts, words.slice(0, 2));
    }

    if (transferProfile && !entity) parts.push(transferProfile);
    if (transferSubangle) parts.push(transferSubangle);

    return parts;
  }

  if (topic === "staff_situation") return ["staff_situation", entity || "staff", staffSituationType || "general"];
  if (topic === "tournament_benefit") return ["tournament_benefit", tournamentBenefitType || "general"];
  if (topic === "award") return ["award", entityGroup || entity || teamUnit || "club", awardType || "general"];
  if (topic === "player_rating") return ["rating", teamUnit || entityGroup || entity || "team", ratingType || "general"];
  if (topic === "club_strategy") return ["club_strategy", entity && isS04StaffEntity(entity) ? entity : "club", clubStrategyType || "general"];
  if (topic === "club_social_buzz") return ["club_social_buzz", socialBuzzType || "general"];
  if (topic === "schalke_affinity") return ["schalke_affinity", entity || "person", affinityType || "general"];
  if (topic === "schalke_multisport") return ["schalke_multisport", entity || "general", multisportType || "general"];
  if (topic === "schalke_legacy") return ["schalke_legacy", entity || "general", legacyType || "general"];
  if (topic === "football_governance") return ["football_governance", entity || "general"];
  if (topic === "dfb_nationalteam") return ["dfb", entity || entityGroup || "schalke_player", dfbCluster || dfbType || "general"];
  if (topic === "fan_service") return ["fan_service", "schalke", fanServiceType || "general"];

  if (topic === "club_event") {
    if (clubEventProduct && clubEventProduct !== clubEventType) return ["club_event", clubEventType || "general", clubEventProduct];
    return ["club_event", clubEventType || "general"];
  }

  if (topic === "finanzen") {
    if (entity && isPlayerEntity(entity)) return ["finanzen", entity, financePhase];
    return ["finanzen", financePhase].concat(words.slice(0, 2));
  }

  if (topic === "aufstellung") return ["aufstellung_match", opponent || "general"];
  if (topic === "tv_service") return ["tv_service", opponent || "general"];
  if (topic === "schiedsrichter") return ["schiedsrichter", opponent || "general"];
  if (topic === "verletzung") return ["verletzung", entity && isPlayerEntity(entity) ? entity : "team", injuryPhase || "general"];

  if (topic === "zukunft") {
    const destinationPart = ["exit", "sale", "loan"].includes(futurePhase) && opponent ? opponent : "";

    if (entity && isPlayerEntity(entity)) return ["spieler_zukunft", entity, futurePhase || "general", destinationPart].filter(Boolean);
    if (entity) return ["zukunft", entity, futurePhase || "general", destinationPart].filter(Boolean);

    return ["zukunft", futurePhase || "general"].concat(words.slice(0, 2));
  }

  if (topic === "aussage") {
    if (entity && speaker) return ["aussage", speaker, "ueber", entity, statementAngle];
    if (entity) return ["aussage", entity, statementAngle];

    return ["aussage"].concat(words.slice(0, 3));
  }

  if (entity) return [topic, entity].concat(words.slice(0, 2));
  if (opponent) return [topic, opponent].concat(words.slice(0, 2));
  if (transferProfile) return [topic, transferProfile].concat(words.slice(0, 2));

  return [topic].concat(words.slice(0, 4));
}

function buildFingerprint(title, description, rawText, url, rawDate) {
  const rawCombined = [title, description, rawText, url].join(" ");
  const baseRaw = normalize(rawCombined);
  const dateBucket = getDateBucketFromRaw(rawDate);
  const publishedAtIso = parseDate(rawDate).toISOString();

  const opponent = detectOpponent(baseRaw);
  const entity = detectEntity(baseRaw, rawCombined);
  const speaker = detectSpeakerEntity(baseRaw, entity);
  const transferProfile = detectTransferProfile(baseRaw);
  const transferPhase = detectTransferPhase(baseRaw);
  const normalizedTransferPhase = normalizeTransferPhaseForDuplicates(transferPhase, baseRaw);
  const transferSubangleInfo = detectTransferSubangle(baseRaw, entity, opponent, speaker);
  const transferSubangle = transferSubangleInfo.subangle;

  const futurePhase = detectFuturePhase(baseRaw);
  const injuryPhase = detectInjuryPhase(baseRaw);
  const statementAngle = detectStatementAngle(baseRaw);
  const financePhase = detectFinancePhase(baseRaw);
  const clubEventType = detectClubEventType(baseRaw);
  const clubEventProduct = detectClubEventProduct(baseRaw);
  const fanServiceType = detectFanServiceType(baseRaw);
  const legacyType = detectLegacyType(baseRaw, entity);
  const dfbType = detectDfbCurrentS04PlayerType(baseRaw, entity);
  const affinityType = detectS04AffinityType(baseRaw);
  const multisportType = detectMultisportType(baseRaw, entity);
  const awardType = detectAwardType(baseRaw);
  const ratingType = detectRatingType(baseRaw);
  const teamUnit = detectTeamUnit(baseRaw);
  const entityGroup = detectEntityGroup(baseRaw, entity);
  const clubStrategyType = detectClubStrategyType(baseRaw, entity);
  const dfbMatchOpponent = detectNationalTeamMatchOpponent(baseRaw);
  const dfbCluster = detectDfbStoryCluster(baseRaw, entity);
  const socialBuzzType = detectClubSocialBuzzType(baseRaw);
  const genericSourceClub = detectGenericSourceClub(baseRaw) || opponent;
  const staffSituationType = detectStaffSituationType(baseRaw, entity);
  const tournamentBenefitType = detectTournamentBenefitType(baseRaw);

  const topic = detectTopic(baseRaw, opponent, entity, speaker);
  const storyTopic = topic === "transfer_geruecht" ? "transfer" : topic;
  const words = uniqueList(cleanWords(baseRaw));

  const storyStageInfo = detectStoryStage(baseRaw, topic, entity, opponent, transferSubangleInfo);
  const storyStage = storyStageInfo.stage;
  const storyStageRank = storyStageInfo.rank;
  const storyStageDetail = storyStageInfo.detail || "";
  const hasHardUpdateSignal = Boolean(storyStageInfo.is_hard_update || detectHardUpdateSignal(baseRaw));

  const storyThreadKey = buildStoryThreadKey(
    storyTopic,
    entity,
    opponent,
    transferProfile,
    words,
    {
      entityGroup: entityGroup,
      teamUnit: teamUnit,
      awardType: awardType,
      clubStrategyType: clubStrategyType,
      dfbMatchOpponent: dfbMatchOpponent,
      dfbCluster: dfbCluster,
      socialBuzzType: socialBuzzType,
      genericSourceClub: genericSourceClub,
      staffSituationType: staffSituationType,
      tournamentBenefitType: tournamentBenefitType
    }
  );

  let keyParts = buildFingerprintParts({
    topic: topic,
    entity: entity,
    opponent: opponent,
    speaker: speaker,
    transferProfile: transferProfile,
    transferSubangle: transferSubangle,
    futurePhase: futurePhase,
    injuryPhase: injuryPhase,
    statementAngle: statementAngle,
    financePhase: financePhase,
    clubEventType: clubEventType,
    clubEventProduct: clubEventProduct,
    fanServiceType: fanServiceType,
    legacyType: legacyType,
    dfbType: dfbType,
    affinityType: affinityType,
    multisportType: multisportType,
    awardType: awardType,
    ratingType: ratingType,
    teamUnit: teamUnit,
    entityGroup: entityGroup,
    clubStrategyType: clubStrategyType,
    dfbCluster: dfbCluster,
    socialBuzzType: socialBuzzType,
    genericSourceClub: genericSourceClub,
    staffSituationType: staffSituationType,
    tournamentBenefitType: tournamentBenefitType,
    words: words
  });

  keyParts = uniqueList(keyParts.map(v => normalizeKey(v)).filter(Boolean));

  const content_fingerprint = [
    dateBucket
  ].concat(keyParts)
    .join("_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "");

  const fingerprint_key = stripDateFromFingerprint(content_fingerprint);

  const story_update_stage_key = [
    storyThreadKey,
    storyStage
  ]
    .map(v => normalizeKey(v))
    .filter(Boolean)
    .join("_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "");

  const duplicate_policy = {
    same_fingerprint_is_duplicate: true,
    same_story_same_stage_window_hours: 6,
    same_story_possible_update_after_hours: 6,
    same_story_require_update_signal_after_hours: 12,
    same_story_higher_stage_is_update: true,
    same_story_same_stage_is_duplicate: true,
    same_story_same_event_is_duplicate: true,
    different_transfer_subangle_is_not_automatic_duplicate: true,
    transfer_same_entity_same_subangle_is_duplicate: true,
    transfer_same_entity_new_subangle_is_update: true,
    transfer_unknown_alternative_same_profile_is_duplicate: true,
    transfer_price_and_cost_package_are_separate_angles: true,
    staff_deadline_duplicates_staff_deadline_not_staff_pressure: true,
    tournament_participants_and_revenue_are_separate: true,
    soft_update_topics: ["transfer", "verletzung", "zukunft", "staff_situation"],
    cluster_duplicate_topics: ["dfb_nationalteam", "award", "player_rating", "club_strategy", "tournament_benefit"]
  };

  return {
    content_fingerprint,
    fingerprint_key,

    story_thread_key: storyThreadKey,
    story_topic: storyTopic,
    story_entity: entity,
    story_opponent: opponent,
    story_speaker: speaker,
    story_stage: storyStage,
    story_stage_rank: storyStageRank,
    story_stage_detail: storyStageDetail,
    story_update_stage_key,
    has_hard_update_signal: hasHardUpdateSignal,
    duplicate_policy,

    published_at_iso: publishedAtIso,

    fingerprint_topic: topic,
    fingerprint_entity: entity,
    fingerprint_entity_type: entityType(entity),
    fingerprint_speaker: speaker,
    fingerprint_is_player_entity: isPlayerEntity(entity),
    fingerprint_is_schalke_player_entity: isS04PlayerEntity(entity),
    fingerprint_is_former_schalke_player_entity: isFormerS04PlayerEntity(entity),
    fingerprint_opponent: opponent,

    fingerprint_transfer_profile: transferProfile,
    fingerprint_transfer_phase: transferPhase,
    fingerprint_transfer_phase_normalized: normalizedTransferPhase,
    fingerprint_transfer_subangle: transferSubangle,
    fingerprint_transfer_subangle_detail: transferSubangleInfo.detail,

    fingerprint_future_phase: futurePhase,
    fingerprint_injury_phase: injuryPhase,
    fingerprint_statement_angle: statementAngle,
    fingerprint_finance_phase: financePhase,

    fingerprint_club_event_type: clubEventType,
    fingerprint_club_event_product: clubEventProduct,
    fingerprint_fan_service_type: fanServiceType,
    fingerprint_legacy_type: legacyType,
    fingerprint_dfb_type: dfbType,
    fingerprint_schalke_affinity_type: affinityType,
    fingerprint_multisport_type: multisportType,

    fingerprint_award_type: awardType,
    fingerprint_rating_type: ratingType,
    fingerprint_team_unit: teamUnit,
    fingerprint_entity_group: entityGroup,
    fingerprint_club_strategy_type: clubStrategyType,
    fingerprint_dfb_match_opponent: dfbMatchOpponent,
    fingerprint_dfb_cluster: dfbCluster,
    fingerprint_social_buzz_type: socialBuzzType,
    fingerprint_generic_source_club: genericSourceClub,
    fingerprint_staff_situation_type: staffSituationType,
    fingerprint_tournament_benefit_type: tournamentBenefitType,

    fingerprint_keywords: keyParts,
    fingerprint_words: words.slice(0, 10),
    fingerprint_date_bucket: dateBucket,
    fingerprint_base: baseRaw
  };
}

function parseRssItems(xml) {
  const raw = String(xml || "");
  const items = [];
  const itemRegex = /<item[\s\S]*?<\/item>/gi;
  let match;

  while ((match = itemRegex.exec(raw)) !== null) {
    const itemXml = match[0];

    const title = stripHtml(getTag(itemXml, "title"));
    const link = stripHtml(getTag(itemXml, "link"));
    const guid = stripHtml(getTag(itemXml, "guid"));
    const pubDateRaw = stripHtml(getTag(itemXml, "pubDate"));
    const description = stripHtml(getTag(itemXml, "description"));
    const contentEncoded = stripHtml(getTag(itemXml, "content:encoded"));

    const url = link || guid;
    const rawText = contentEncoded || description || "";

    if (!title && !url) continue;

    const fp = buildFingerprint(title, description, rawText, url, pubDateRaw);

    items.push({
      title,
      description,
      raw_text: rawText,
      url,
      source_url: url,
      published_at: normalizeDate(pubDateRaw),
      published_at_raw: pubDateRaw,
      source: "schalketotal",
      source_type: "wordpress_rss",

      content_fingerprint: fp.content_fingerprint,
      fingerprint_key: fp.fingerprint_key,

      story_thread_key: fp.story_thread_key,
      story_topic: fp.story_topic,
      story_entity: fp.story_entity,
      story_opponent: fp.story_opponent,
      story_speaker: fp.story_speaker,
      story_stage: fp.story_stage,
      story_stage_rank: fp.story_stage_rank,
      story_stage_detail: fp.story_stage_detail,
      story_update_stage_key: fp.story_update_stage_key,
      has_hard_update_signal: fp.has_hard_update_signal,
      duplicate_policy: fp.duplicate_policy,

      published_at_iso: fp.published_at_iso,

      fingerprint_topic: fp.fingerprint_topic,
      fingerprint_entity: fp.fingerprint_entity,
      fingerprint_entity_type: fp.fingerprint_entity_type,
      fingerprint_speaker: fp.fingerprint_speaker,
      fingerprint_is_player_entity: fp.fingerprint_is_player_entity,
      fingerprint_is_schalke_player_entity: fp.fingerprint_is_schalke_player_entity,
      fingerprint_is_former_schalke_player_entity: fp.fingerprint_is_former_schalke_player_entity,
      fingerprint_opponent: fp.fingerprint_opponent,

      fingerprint_transfer_profile: fp.fingerprint_transfer_profile,
      fingerprint_transfer_phase: fp.fingerprint_transfer_phase,
      fingerprint_transfer_phase_normalized: fp.fingerprint_transfer_phase_normalized,
      fingerprint_transfer_subangle: fp.fingerprint_transfer_subangle,
      fingerprint_transfer_subangle_detail: fp.fingerprint_transfer_subangle_detail,

      fingerprint_future_phase: fp.fingerprint_future_phase,
      fingerprint_injury_phase: fp.fingerprint_injury_phase,
      fingerprint_statement_angle: fp.fingerprint_statement_angle,
      fingerprint_finance_phase: fp.fingerprint_finance_phase,

      fingerprint_club_event_type: fp.fingerprint_club_event_type,
      fingerprint_club_event_product: fp.fingerprint_club_event_product,
      fingerprint_fan_service_type: fp.fingerprint_fan_service_type,
      fingerprint_legacy_type: fp.fingerprint_legacy_type,
      fingerprint_dfb_type: fp.fingerprint_dfb_type,
      fingerprint_schalke_affinity_type: fp.fingerprint_schalke_affinity_type,
      fingerprint_multisport_type: fp.fingerprint_multisport_type,

      fingerprint_award_type: fp.fingerprint_award_type,
      fingerprint_rating_type: fp.fingerprint_rating_type,
      fingerprint_team_unit: fp.fingerprint_team_unit,
      fingerprint_entity_group: fp.fingerprint_entity_group,
      fingerprint_club_strategy_type: fp.fingerprint_club_strategy_type,
      fingerprint_dfb_match_opponent: fp.fingerprint_dfb_match_opponent,
      fingerprint_dfb_cluster: fp.fingerprint_dfb_cluster,
      fingerprint_social_buzz_type: fp.fingerprint_social_buzz_type,
      fingerprint_generic_source_club: fp.fingerprint_generic_source_club,
      fingerprint_staff_situation_type: fp.fingerprint_staff_situation_type,
      fingerprint_tournament_benefit_type: fp.fingerprint_tournament_benefit_type,

      fingerprint_keywords: fp.fingerprint_keywords,
      fingerprint_words: fp.fingerprint_words,
      fingerprint_date_bucket: fp.fingerprint_date_bucket,
      fingerprint_base: fp.fingerprint_base
    });
  }

  return items;
}

