function normalize(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/<img[^>]*>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/https?:\/\/\S+/gi, " ")
    .replace(/&[a-z0-9#]+;/gi, " ")
    .replace(/[^\w\säöüß\-\/]/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function stripDateFromFingerprint(fp) {
  return String(fp || "").replace(/^\d{4}-\d{2}-\d{2}_/, "");
}

function getDateFromFingerprint(fp) {
  const match = String(fp || "").match(/^(\d{4}-\d{2}-\d{2})_/);
  return match ? match[1] : "";
}

function parseDateToBucket(value, fallbackFingerprint = "") {
  const fromFingerprint = getDateFromFingerprint(fallbackFingerprint);

  const raw = String(value || "").trim();

  if (!raw) {
    return fromFingerprint || "";
  }

  const cleaned = raw
    .replace(/\bCEST\b/gi, "+0200")
    .replace(/\bCET\b/gi, "+0100");

  const date = new Date(cleaned);

  if (Number.isNaN(date.getTime())) {
    return fromFingerprint || "";
  }

  return date.toISOString().slice(0, 10);
}

function daysBetween(dateA, dateB) {
  if (!dateA || !dateB) return null;

  const a = new Date(`${dateA}T00:00:00.000Z`);
  const b = new Date(`${dateB}T00:00:00.000Z`);

  if (Number.isNaN(a.getTime()) || Number.isNaN(b.getTime())) {
    return null;
  }

  return Math.abs(Math.round((a.getTime() - b.getTime()) / 86400000));
}

function hasUpdateSignal(item) {
  const text = normalize(
    [
      item.title,
      item.source_title,
      item.description,
      item.raw_text,
      item.url,
      item.source_url
    ].join(" ")
  );

  const updatePatterns = [
    /\bupdate\b/,
    /\bneue infos\b/,
    /\bneue details\b/,
    /\bneue entwicklung\b/,
    /\bneuer stand\b/,
    /\bneue lage\b/,
    /\bneue wendung\b/,
    /\bwende\b/,
    /\bkehrtwende\b/,
    /\bentscheidung\b/,
    /\bentschieden\b/,
    /\beinigung\b/,
    /\bdurchbruch\b/,
    /\bangebot\b/,
    /\bneues angebot\b/,
    /\bgespräche\b/,
    /\bgespraeche\b/,
    /\bverhandlungen\b/,
    /\bberater\b/,
    /\bbestätigt\b/,
    /\bbestaetigt\b/,
    /\bbestätigung\b/,
    /\bbestaetigung\b/,
    /\babsage\b/,
    /\babgelehnt\b/,
    /\bkonkret\b/,
    /\bkonkreter\b/,
    /\bnächster schritt\b/,
    /\bnaechster schritt\b/,
    /\bmacht ernst\b/,
    /\brückt näher\b/,
    /\brueckt naeher\b/,
    /\bnimmt fahrt auf\b/,
    /\bplan b\b/,
    /\balternative\b/,
    /\bneuer kandidat\b/,
    /\bneue option\b/,
    /\bfrische spur\b/
  ];

  return updatePatterns.some(pattern => pattern.test(text));
}

function cleanWords(text) {
  const noise = new Set([
    "der", "die", "das", "ein", "eine", "einer", "einen", "einem",
    "und", "oder", "aber", "auch", "mit", "bei", "von", "vor", "nach",
    "zum", "zur", "auf", "für", "fuer", "im", "am", "an", "aus", "des", "den",
    "dem", "ist", "sind", "war", "waren", "wird", "werden", "hat", "haben",
    "nicht", "mehr", "noch", "weiter", "wieder", "will", "soll", "kann",
    "könnte", "koennte", "steht", "zieht", "offenbar", "wohl", "jetzt",
    "doch", "neue", "neuer", "neues", "news", "bericht", "berichte",
    "fc", "schalke", "gelsenkirchen", "gelsenkirchen", "s04", "star", "spieler",
    "profi", "trainer", "boss", "chef", "spiel", "partie", "duell",
    "gegen", "bundesliga", "champions", "league", "cl", "artikel",
    "transfer", "wechsel", "zukunft", "vertrag", "sommer"
  ]);

  return normalize(text)
    .split(" ")
    .map(w => w.trim())
    .filter(w => w.length >= 4)
    .filter(w => !noise.has(w))
    .map(w => {
      if (w === "karamans") return "karaman";
      if (w === "syllas") return "sylla";
      if (w === "kalass") return "kalas";
      if (w === "lasmes") return "lasme";
      if (w === "porahts") return "porath";
      if (w === "becker") return "becker";
      if (w.endsWith("s") && w.length > 6) return w.replace(/s$/, "");
      return w;
    })
    .filter(w => !noise.has(w));
}

function similarity(textA, textB) {
  const a = new Set(cleanWords(textA));
  const b = new Set(cleanWords(textB));

  if (a.size === 0 || b.size === 0) return 0;

  let intersection = 0;

  for (const word of a) {
    if (b.has(word)) intersection++;
  }

  const union = new Set([...a, ...b]).size;

  return union ? intersection / union : 0;
}

const schalketotalRows = schalketotalItems
  .map(item => item.json || {})
  .filter(row => row.fingerprint_key || row.content_fingerprint)
  .map(row => {
    const contentFingerprint = row.content_fingerprint || "";
    const fingerprintKey =
      row.fingerprint_key ||
      stripDateFromFingerprint(contentFingerprint);

    return {
      ...row,
      content_fingerprint: contentFingerprint,
      fingerprint_key: fingerprintKey,
      date_bucket: parseDateToBucket(row.published_at || row.created_at, contentFingerprint),
      title_normalized: normalize(row.title || "")
    };
  });

const out = [];
const removed = [];

for (const item of externalItems) {
  const json = item.json || {};

  const externalFingerprint = json.content_fingerprint || "";
  const externalKey =
    json.fingerprint_key ||
    stripDateFromFingerprint(externalFingerprint);

  const externalDate =
    json.fingerprint_date_bucket ||
    parseDateToBucket(
      json.published_at ||
      json.publishedAt ||
      json.pubDate ||
      json.isoDate ||
      json.date ||
      json.created_at,
      externalFingerprint
    );

  const externalTitle =
    json.title ||
    json.source_title ||
    "";

  const externalTextForSimilarity = [
    json.title,
    json.source_title,
    json.description
  ].join(" ");

  const updateSignal = hasUpdateSignal(json);

  if (!externalFingerprint && !externalKey) {
    out.push({
      json: {
        ...json,
        schalketotal_duplicate_status: "check_skipped_no_fingerprint",
        schalketotal_duplicate_reason: "no_content_fingerprint_or_fingerprint_key"
      }
    });
    continue;
  }

  let shouldRemove = false;
  let matchedRow = null;
  let removeReason = "";
  let bestSimilarity = 0;
  let bestDaysDiff = null;

  const candidates = schalketotalRows.filter(row => {
    if (!row.fingerprint_key || !externalKey) return false;
    return row.fingerprint_key === externalKey;
  });

  for (const row of candidates) {
    const daysDiff = daysBetween(externalDate, row.date_bucket);

    const sim = similarity(
      externalTextForSimilarity,
      row.title || ""
    );

    if (sim > bestSimilarity) {
      bestSimilarity = sim;
      bestDaysDiff = daysDiff;
    }

    // 1. Exakter Fingerprint inklusive Datum: sicher gleiche Story
    if (
      externalFingerprint &&
      row.content_fingerprint &&
      externalFingerprint === row.content_fingerprint
    ) {
      shouldRemove = true;
      matchedRow = row;
      removeReason = "exact_content_fingerprint_match";
      bestSimilarity = sim;
      bestDaysDiff = daysDiff;
      break;
    }

    // 2. Gleicher Themenkey am selben Tag: sehr wahrscheinlich schon vorhanden
    if (daysDiff === 0) {
      shouldRemove = true;
      matchedRow = row;
      removeReason = "same_fingerprint_key_same_day";
      bestSimilarity = sim;
      bestDaysDiff = daysDiff;
      break;
    }

    // 3. 1–2 Tage Unterschied: nur blocken, wenn sehr ähnlich UND kein Update-Signal
    if (
      daysDiff !== null &&
      daysDiff <= 2 &&
      sim >= 0.72 &&
      !updateSignal
    ) {
      shouldRemove = true;
      matchedRow = row;
      removeReason = `same_fingerprint_key_recent_similar_title_${sim.toFixed(2)}`;
      bestSimilarity = sim;
      bestDaysDiff = daysDiff;
      break;
    }

    // 4. Älter als 2 Tage: nur extrem ähnliche Titel blocken
    if (
      daysDiff !== null &&
      daysDiff > 2 &&
      sim >= 0.90 &&
      !updateSignal
    ) {
      shouldRemove = true;
      matchedRow = row;
      removeReason = `old_but_extremely_similar_title_${sim.toFixed(2)}`;
      bestSimilarity = sim;
      bestDaysDiff = daysDiff;
      break;
    }
  }

  if (shouldRemove && matchedRow) {
    removed.push({
      external_title: externalTitle,
      external_url: json.url || json.source_url || "",
      external_content_fingerprint: externalFingerprint,
      external_fingerprint_key: externalKey,
      external_date: externalDate,

      matched_schalketotal_title: matchedRow.title || "",
      matched_schalketotal_url: matchedRow.url || "",
      matched_schalketotal_content_fingerprint: matchedRow.content_fingerprint || "",
      matched_schalketotal_fingerprint_key: matchedRow.fingerprint_key || "",
      matched_schalketotal_date: matchedRow.date_bucket || "",

      reason: removeReason,
      title_similarity: Number(bestSimilarity.toFixed(2)),
      days_difference: bestDaysDiff,
      update_signal: updateSignal
    });

    continue;
  }

  out.push({
    json: {
      ...json,
      schalketotal_duplicate_status:
        candidates.length > 0
          ? "same_topic_but_allowed"
          : "unique_against_schalketotal",
      schalketotal_duplicate_reason:
        candidates.length > 0
          ? (
              updateSignal
                ? "same_fingerprint_key_but_update_signal"
                : "same_fingerprint_key_but_not_close_enough"
            )
          : "no_matching_schalketotal_fingerprint_key",
      schalketotal_candidates_found: candidates.length,
      schalketotal_best_similarity: Number(bestSimilarity.toFixed(2)),
      schalketotal_best_days_difference: bestDaysDiff,
      schalketotal_update_signal: updateSignal,
      schalketotal_checked_rows: schalketotalRows.length
    }
  });
}

if (out.length > 0) {
  out[0].json.schalketotal_duplicates_removed = removed.length;
  out[0].json.schalketotal_duplicates_examples = removed.slice(0, 10);
}

return out;

