const output = [];

function cleanText(value) {
  return String(value || "")
    .replace(/https?:\/\/\S+/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeHandle(value) {
  return String(value || "")
    .replace(/^@/, "")
    .trim();
}

function getUrl(item) {
  return (
    item.url ||
    item.twitterUrl ||
    item.tweetUrl ||
    item.link ||
    ""
  );
}

function getText(item) {
  return (
    item.text ||
    item.fullText ||
    item.tweetText ||
    item.content ||
    ""
  );
}

function getCreatedAt(item) {
  return (
    item.createdAt ||
    item.created_at ||
    item.date ||
    item.timestamp ||
    ""
  );
}

function getAuthorHandle(item, url) {
  const direct =
    item.author?.userName ||
    item.author?.username ||
    item.author?.screenName ||
    item.user?.userName ||
    item.user?.username ||
    item.user?.screenName ||
    item.username ||
    item.userName ||
    item.handle ||
    "";

  if (direct) return normalizeHandle(direct);

  const match = String(url || "").match(/x\.com\/([^/]+)\/status/i) ||
    String(url || "").match(/twitter\.com\/([^/]+)\/status/i);

  return match ? normalizeHandle(match[1]) : "";
}

