  const data = item.json || {};

  const url = getUrl(data);
  const rawText = getText(data);
  const published_at = getCreatedAt(data);
  const account_handle = getAuthorHandle(data, url);

  if (!url || !rawText) continue;

  const text = cleanText(rawText);

  /**
   * Replies/Retweets grob rausfiltern.
   * Der Actor sollte das schon machen, aber das ist ein zusätzlicher Schutz.
   */
  const lower = text.toLowerCase();

  const isLikelyReply =
    lower.startsWith("@") &&
    !lower.includes("schalke") &&
    !lower.includes("schalke") &&
    !lower.includes("schalke");

  const isLikelyRetweet =
    lower.startsWith("rt @");

  if (isLikelyReply || isLikelyRetweet) continue;

  output.push({
    json: {
      source: "x",
      source_type: "x_post",
      source_category: "football_x_sources",

      account_handle,
      account_url: account_handle ? `https://x.com/${account_handle}` : "",
