      x_quote_count: data.quoteCount ?? data.quotes ?? null,
      x_view_count: data.viewCount ?? data.views ?? null
    }
  });
}

return output;

// Prepare Title Style Rules For Prompt
// Erstellt einen kompakten dynamischen Regelblock für die Titelgenerierung.
// Ziel: nicht die neuesten Regeln nehmen, sondern die besten passenden Titel-/Social-Regeln.
// Auswahl-Logik:
// - approved + general + title_prompt/both
// - Score nach Priorität, Konfidenz, Änderungsstärke, Regeltyp, Zielprompt
// - Recency nur kleiner Bonus, niemals Hauptkriterium
// - artikelreine Regeln werden ausgeschlossen
// - ähnliche Regeln / gleiche Cluster reduzieren
// - maximal 8 Regeln für den Titel-/Social-Prompt

const MAX_RULES_TOTAL = 8;

const MAX_PER_CLUSTER = {
  title_core: 1,
  title_hook: 1,
  title_quote: 1,
  title_specificity: 1,
  schalke_focus: 1,
  framing_accuracy: 1,
  timing_context: 1,
  priority_tone: 1,
  social_caption: 1,
  source_handling: 1,
  general: 2,
};

function clean(value) {
  return String(value ?? '').trim();
}

function normalizeText(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[„“"‚‘’'`´]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function isUsefulPromptRule(ruleText) {
  const text = normalizeText(ruleText);

  if (!text) return false;

  const uselessPatterns = [
    'keine zusätzliche regel',
    'keine regel abgeleitet',
    'keine regel ableiten',
    'kein zusätzlicher regelbedarf',
    'kein verbesserungsbedarf',
    'sollte daraus keine zusätzliche',
    'sollte dafür keine zusätzliche',
    'generated und final identisch',
    'final und generated identisch',
    'titel bereits identisch',
    'wenn titel bereits identisch',
    'wenn generated title und final title identisch',
    'wenn der generierte titel bereits',
    'titel unverändert beibehalten',
    'titel sollte unverändert beibehalten werden',
    'final sind und',
    'meta generated und final',
    'generated meta und final meta',
  ];

  return !uselessPatterns.some(pattern => text.includes(pattern));
}

function isArticleOnlyRule(rule) {
  const area = normalizeText(rule.rule_area);
  const text = normalizeText(rule.rule_text);
  const combined = `${area} ${text}`;

  const articleOnlySignals = [
    'einleitung',
    'erster absatz',
    'erster hauptabsatz',
    'hauptabsatz',
    'zwischenüberschrift',
    'artikelstruktur',
    'article structure',
    'article_structure',
    'absatz',
    'paragraph',
    'generated_article',
    'final_article',
    'artikelentwurf',
    'wp_tags',
    'meta description',
    'focus keyphrase',
    'wordpress',
    'draft_status',
    'zitate im artikel',
    'direkte zitate im artikel',
    'jeder absatz',
    'artikel soll',
    'artikel darf',
  ];

  return articleOnlySignals.some(signal => combined.includes(signal));
}

function priorityScore(priority) {
  const value = clean(priority).toLowerCase();

  if (value === 'high') return 40;
  if (value === 'medium') return 25;
  if (value === 'low') return 10;

  return 0;
}

function confidenceScore(confidence) {
  const value = clean(confidence).toLowerCase();

  if (value === 'high') return 12;
  if (value === 'medium') return 6;
  if (value === 'low') return 2;

  return 0;
}

function changeLevelScore(changeLevel) {
  const value = clean(changeLevel).toLowerCase();

  if (value === 'major') return 14;
  if (value === 'medium') return 9;
  if (value === 'minor') return 3;
  if (value === 'none') return 0;

  return 0;
}

function ruleKindScore(ruleKind) {
  const value = clean(ruleKind).toLowerCase();

  if (value === 'derived_rule') return 10;
  if (value === 'prompt_improvement') return 7;

  return 4;
}

function ruleTypeScore(ruleType) {
  const value = clean(ruleType).toLowerCase();

  if (value === 'sharpen_existing_rule') return 10;
  if (value === 'new_rule') return 8;
  if (value === 'compliance_reminder') return 5;
  if (value === 'prompt_improvement') return 6;

  return 3;
}

function targetPromptScore(targetPrompt) {
  const value = clean(targetPrompt).toLowerCase();

  if (value === 'title_prompt') return 14;
  if (value === 'both') return 6;

  return 0;
}

function approvedExampleScore(value) {
  const text = clean(value).toLowerCase();

  if (text === 'ja' || text === 'yes' || text === 'true') return 8;

  return 0;
}

function recencyScore(approvedAt) {
  const dateValue = clean(approvedAt);
  if (!dateValue) return 0;

  const timestamp = Date.parse(dateValue);
  if (Number.isNaN(timestamp)) return 0;

  const ageDays = (Date.now() - timestamp) / (1000 * 60 * 60 * 24);

  if (ageDays <= 7) return 3;
  if (ageDays <= 30) return 2;
  if (ageDays <= 90) return 1;

  return 0;
}

function specificityScore(ruleText) {
  const text = clean(ruleText);
  const length = text.length;

  if (length < 30) return 0;
  if (length <= 100) return 8;
  if (length <= 220) return 10;
  if (length <= 360) return 6;

  return 2;
}

function titleAreaBonus(rule) {
  const area = normalizeText(rule.rule_area);
  const text = normalizeText(rule.rule_text);
  const combined = `${area} ${text}`;

  if (
    area === 'title' ||
    area === 'headline' ||
    combined.includes('titel') ||
    combined.includes('headline') ||
    combined.includes('überschrift') ||
    combined.includes('social teaser') ||
    combined.includes('social caption')
  ) {
    return 12;
  }

  return 0;
}

function getRuleCluster(rule) {
  const area = normalizeText(rule.rule_area);
  const text = normalizeText(rule.rule_text);
  const combined = `${area} ${text}`;

  if (
    combined.includes('zitat') ||
    combined.includes('originalzitat') ||
    combined.includes('direktes zitat') ||
    combined.includes('starkes zitat') ||
    combined.includes('aussage') ||
    combined.includes('statement')
  ) {
    return 'title_quote';
  }

  if (
    combined.includes('hook') ||
    combined.includes('aufhänger') ||
    combined.includes('teaser') ||
    combined.includes('neugier') ||
    combined.includes('anteasern') ||
    combined.includes('klickstark') ||
    combined.includes('zweiteilig')
  ) {
    return 'title_hook';
  }

  if (
    combined.includes('konkreter kern') ||
    combined.includes('kern der nachricht') ||
    combined.includes('nachrichtenkern') ||
    combined.includes('hauptnachricht') ||
    combined.includes('nicht generisch') ||
    combined.includes('generisch') ||
    combined.includes('konkret')
  ) {
    return 'title_core';
  }

  if (
    combined.includes('originaltitel') ||
    combined.includes('originalkern') ||
    combined.includes('originalformulierung') ||
    combined.includes('starke originalformulierung') ||
    combined.includes('nicht abstrahieren') ||
    combined.includes('nicht weichspülen')
  ) {
    return 'title_specificity';
  }

  if (
    combined.includes('schalke fokus') ||
    combined.includes('schalke focus') ||
    combined.includes('schalke bezug') ||
    combined.includes('schalke relevanz') ||
    combined.includes('schalke relevant') ||
    combined.includes('schalke aufhänger') ||
    area === 'schalke_focus' ||
    area === 'schalke focus' ||
    area === 'schalke fokus'
  ) {
    return 'schalke_focus';
  }

  if (
    combined.includes('framing') ||
    combined.includes('rückschlag') ||
    combined.includes('gegner news') ||
    combined.includes('gegner-news') ||
    combined.includes('wirkung behaupten') ||
    combined.includes('nicht dramatisieren') ||
    combined.includes('überdramatisieren') ||
    combined.includes('reißerisch')
  ) {
    return 'framing_accuracy';
  }

  if (
    combined.includes('vor dem spiel') ||
    combined.includes('nach dem spiel') ||
    combined.includes('zeitlicher kontext') ||
    combined.includes('vorschau') ||
    combined.includes('reaktion') ||
    combined.includes('hinspiel') ||
    combined.includes('rückspiel')
  ) {
    return 'timing_context';
  }

  if (
    combined.includes('priorität') ||
    combined.includes('priority') ||
    combined.includes('high') ||
    combined.includes('medium') ||
    combined.includes('low') ||
    combined.includes('ton') ||
    combined.includes('alarmton')
  ) {
    return 'priority_tone';
  }

  if (
    combined.includes('social') ||
    combined.includes('caption') ||
    combined.includes('social teaser') ||
    combined.includes('teaser soll') ||
    combined.includes('headline nicht wiederholen')
  ) {
    return 'social_caption';
  }

  if (
    combined.includes('quelle') ||
    combined.includes('quellen') ||
    combined.includes('quellenangabe') ||
    combined.includes('sendungsangabe') ||
    combined.includes('medium') ||
    combined.includes('journalist')
  ) {
    return 'source_handling';
  }

  if (
    area === 'title' ||
    area === 'headline'
  ) {
    return 'title_core';
  }

  return area || 'general';
}

function keywordSet(text) {
  const stopwords = new Set([
    'der', 'die', 'das', 'ein', 'eine', 'einer', 'eines', 'und', 'oder', 'aber',
    'wenn', 'dann', 'soll', 'sollen', 'muss', 'müssen', 'darf', 'dürfen',
    'nicht', 'nur', 'mit', 'von', 'für', 'bei', 'im', 'in', 'am', 'an', 'auf',
    'zu', 'als', 'nach', 'durch', 'werden', 'wird', 'wurde', 'dem', 'den',
    'des', 'ist', 'sind', 'wie', 'etwa', 'auch', 'mehr', 'klar', 'konkret'
  ]);

  return new Set(
    normalizeText(text)
      .split(' ')
      .filter(word => word.length >= 5 && !stopwords.has(word))
      .map(word =>
        word
          .replace(/überschriften/g, 'überschrift')
          .replace(/headlines/g, 'headline')
          .replace(/titeln/g, 'titel')
          .replace(/titelregel/g, 'titel')
          .replace(/generischen/g, 'generisch')
          .replace(/konkreter/g, 'konkret')
          .replace(/konkreten/g, 'konkret')
          .replace(/dramatisieren/g, 'dramatisier')
          .replace(/dramatisierung/g, 'dramatisier')
      )
  );
}

function jaccardSimilarity(aText, bText) {
  const a = keywordSet(aText);
  const b = keywordSet(bText);

  if (a.size === 0 || b.size === 0) return 0;

  let intersection = 0;

  for (const word of a) {
    if (b.has(word)) intersection++;
  }

  const union = new Set([...a, ...b]).size;

  return intersection / union;
}

function areSimilarRules(a, b) {
  const aCluster = getRuleCluster(a);
  const bCluster = getRuleCluster(b);

  const sameCluster = aCluster && bCluster && aCluster === bCluster;
  const similarity = jaccardSimilarity(a.rule_text, b.rule_text);

  if (sameCluster) return true;
  if (similarity >= 0.42) return true;

  return false;
}

function calculateRuleScore(rule) {
  return (
    priorityScore(rule.rule_priority) +
    confidenceScore(rule.ai_confidence) +
    changeLevelScore(rule.article_change_level) +
    ruleKindScore(rule.rule_kind) +
    ruleTypeScore(rule.rule_type) +
    targetPromptScore(rule.target_prompt) +
    approvedExampleScore(rule.approved_example) +
    specificityScore(rule.rule_text) +
    titleAreaBonus(rule) +
    recencyScore(rule.approved_at)
  );
}

function isApprovedTitleRule(rule) {
  const status = clean(rule.rule_status);
  const generalization = clean(rule.generalization_level || 'general');
  const target = clean(rule.target_prompt);
