function extractText(json) {
  if (typeof json === "string") return json;

  if (json.text) return json.text;

  if (json.output) {
    if (typeof json.output === "string") return json.output;

    if (Array.isArray(json.output)) {
      const first = json.output[0];

      if (typeof first === "string") return first;

      if (first?.content && Array.isArray(first.content)) {
        const textPart = first.content.find(part => part.type === "output_text" || part.text);
        if (textPart?.text) return textPart.text;
      }

      if (first?.text) return first.text;
      if (first?.message?.content) return first.message.content;
    }
  }

  if (json.response) return json.response;
  if (json.message) return json.message;

  if (json.content) {
    if (typeof json.content === "string") return json.content;

    if (Array.isArray(json.content)) {
      const textPart = json.content.find(part => part.type === "output_text" || part.text);
      if (textPart?.text) return textPart.text;
    }
  }

  if (json.choices?.[0]?.message?.content) {
    return json.choices[0].message.content;
  }

  return JSON.stringify(json);
}

function parseJsonLoose(value) {
  if (typeof value === "object" && value !== null) {
    if (
      value.is_s04_relevant_ai !== undefined ||
      value.ai_action ||
      value.ai_duplicate_decision ||
      value.recommended_action ||
      value.duplicate_decision
    ) {
      return value;
    }
  }

  const text = extractText(value).trim();

  try {
    return JSON.parse(text);
  } catch (e) {
    const cleaned = text
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/```$/i, "")
      .trim();

    try {
      return JSON.parse(cleaned);
    } catch (e2) {
      const match = cleaned.match(/\{[\s\S]*\}/);
      if (match) {
        return JSON.parse(match[0]);
      }
      throw e2;
    }
  }
}

function normalizeString(value, fallback = "") {
  return String(value ?? fallback).trim();
}

function normalizeNumber(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function normalizeBoolean(value, fallback = null) {
  if (value === true) return true;
  if (value === false) return false;

  const stringValue = String(value ?? "").trim().toLowerCase();

  if (stringValue === "true") return true;
  if (stringValue === "false") return false;

  return fallback;
}

function normalizeAllowed(value, allowedValues, fallback) {
  const normalized = normalizeString(value).toLowerCase();
  return allowedValues.includes(normalized) ? normalized : fallback;
}

