  const selectedTitleStyleExamples = examples.map(example => {
    return [
      `Beispiel ${example.index}`,
      `Cluster: ${example.topic_cluster}`,
      example.topic_type ? `Topic Type: ${example.topic_type}` : "",
      example.subtype ? `Subtype: ${example.subtype}` : "",
      example.example_title ? `Headline: ${example.example_title}` : "",
      example.example_intro ? `Einleitung: ${example.example_intro}` : "",
      example.example_h2 ? `H2: ${example.example_h2}` : "",
      example.style_notes ? `Stilnotiz: ${example.style_notes}` : "",
      example.structure_notes ? `Strukturnotiz: ${example.structure_notes}` : ""
    ]
      .filter(Boolean)
      .join("\n");
  }).join("\n\n---\n\n");

  return {
    selectedTitleStyleExamples,
    examplesCount: examples.length,
    strategy: {
      target_cluster: targetCluster,
      target_topic_type: targetTopicType,
      exact_cluster_available: exactClusterExamples.length,
      same_topic_available: sameTopicExamples.length,
      fallback_available: fallbackExamples.length,
      total_examples_available: exampleRows.length
    }
  };
}

return currentItems.map(currentRaw => {
  const current = { ...currentRaw };
  delete current._row_type;

  const result = buildExamplesFor(current);

  return {
    json: {
      ...current,
      selected_title_style_examples: result.selectedTitleStyleExamples,
      selected_title_style_examples_count: result.examplesCount,
      selected_title_style_examples_strategy: result.strategy
    }
  };
});
